L["A beautiful visual refresh of Blizzard Bags with intuitive organization."] = "Eine optisch ansprechende Überarbeitung der Blizzard Taschen mit intuitiver Organisation."
L["A blank bar to build from scratch."] = "Eine leere Leiste, die man von Grund auf neu gestalten kann."
L["A bright, minimalist layout with a clean aesthetic. Crafted for any role with clear information and a calm but focused feel."] = "Ein helles, minimalistisches Layout mit einer sauberen Ästhetik. Entwickelt für jede Rolle, mit übersichtlichen Informationen und einer ruhigen, aber fokussierten Atmosphäre."
L["a Buff bar"] = "eine Buffleiste"
L["a buff/aura"] = "ein Buff/eine Aura"
L["A CDM replacement focused on performance, customizations and alerts."] = "Ein CDM Ersatz mit Fokus auf Performance, Anpassungsmöglichkeiten und Warnungen."
L["A clean minimal setup"] = "Ein sauberes, minimalistisches Setup"
L["A clean, airy layout with a calm feel and clear information at a glance. Comfortable for long sessions in any content."] = "Ein aufgeräumtes, luftiges Layout mit ruhiger Anmutung und allen wichtigen Informationen auf einen Blick. Angenehm für lange Spielsitzungen in jedem Inhalt."
L["A clean, updated reskin of Blizzard's Quest Tracker."] = "Ein sauberes, modernisiertes Design für Blizzards Questverfolgung."
L["a Cooldown or Utility bar"] = "eine Abklingzeit- oder Dienstbarkeitsleiste"
L["a cooldown"] = "eine Abklingzeit"
L["A dark, elegant healing setup built around raid frames and a clean display of information to help keep your team alive at a glance."] = "Ein dunkles, elegantes Heiler Setup, das um die Schlachtzugsfenster herum aufgebaut ist. Bietet eine übersichtliche Informationsanzeige, um dein Team auf einen Blick am Leben zu erhalten."
L["a Dispel Glow Style"] = "ein Bann Leuchtstil"
L["A Horizontally Growing Anchor Target"] = "Ein horizontal wachsendes Verankerungsziel"
L["A luminous healing setup built around raid frames and crisp readability, keeping your team's health front and center at a glance."] = "Ein leuchtendes Heil Setup rund um Schlachtzugsfenster und gestochen scharfe Lesbarkeit, das die Gesundheit deines Teams auf einen Blick im Zentrum hält."
L["a Mail Position corner"] = "eine Ecke für die Post Position"
L["A modern friends list with built-in organization tools."] = "Eine moderne Freundesliste mit integrierten Organisationswerkzeugen."
L["A new age minimap with clean styling and square layout options."] = "Eine moderne Minikarte mit sauberem Design und Optionen für ein quadratisches Layout."
L["A new built-in profile preset: the damage dealer cut of Midnight Lily, a focused low-clutter layout that keeps your rotation and cooldowns front and center."] = "Eine neue integrierte Profilvoreinstellung: Die DPS Version von „Midnight Lily“ – ein fokussiertes, aufgeräumtes Layout, das deine Rotation und Abklingzeiten in den Mittelpunkt stellt."
L["A new option that makes enemy nameplates pulse with a red glow the moment a target drops below 30% health, so a whole pack tells you at a glance which mobs are in execute range."] = "Eine neue Option, die gegnerische Namensplaketten rot pulsieren lässt, sobald ein Ziel unter 30% Gesundheit fällt. So siehst du bei einer ganzen Gruppe auf einen Blick, welche Mobs in Hinrichten-Reichweite sind."
L["A profile named \"%1$s\" already exists. Please choose a different name."] = "Ein Profil mit dem Namen „%1$s“ existiert bereits. Bitte wähle einen anderen Namen."
L["A raid control panel with ready check, pull timer and raid markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "Ein Schlachtzugs Bedienfeld mit Bereitschaftscheck, Pull Timer und Schlachtzugsmarkierungen. In einem Schlachtzug wird es nur angezeigt, wenn Du der Leiter oder ein Assistent bist, da ohne diese Rechte keine der Tasten funktioniert; in einer Gruppe wird es immer angezeigt."
L["A shadowed, understated layout that keeps the screen quiet and the essentials close. Information appears exactly when you need it."] = "Ein schattiges, dezent gehaltenes Layout, das den Bildschirm ruhig hält und das Wesentliche griffbereit hat. Informationen erscheinen genau dann, wenn du sie brauchst."
L["A simple Mythic+ timer with full tracking customizations."] = "Ein einfacher Mythisch+ Timer mit umfassenden Anpassungsmöglichkeiten für die Verfolgung."
L["A spec override owns this setting, so this conditional value never applies outside an editing session. Remove the spec override to let it through."] = "Eine Spezialisierungs Überschreibung steuert diese Einstellung, daher wird dieser bedingte Wert außerhalb einer Bearbeitungssitzung nie angewendet. Entferne die Spezialisierungs-Überschreibung, um ihn zuzulassen."
L["A standalone cast bar for this unit, placeable anywhere in Unlock Mode. Runs alongside the Unit Frames cast bars."] = "Eine eigenständige Zauberleiste für diese Einheit, die im Freigabemodus überall platziert werden kann. Läuft parallel zu den Zauberleisten der Einheitenfenster."
L["A sync group needs at least two profiles"] = "Eine Synchronisationsgruppe benötigt mindestens zwei Profile"
L["a Target or Focus Cast Bar"] = "eine Ziel- oder Fokus Zauberleiste"
L["a tertiary stat in Stats to Show"] = "einen tertiären Wert in 'Anzuzeigende Werte'"
L["a Toggled Menu Select Action keybind"] = "eine Tastenbelegung für 'Aktion für offenes Menü auswählen'"
L["A UI reload is needed to add this icon to the sidebar."] = "Ein Neuladen des Interfaces ist erforderlich, um dieses Symbol der Seitenleiste hinzuzufügen."
