L["Adds a 'Train All' button next to the Train button at profession trainers, allowing you to learn all available skills with one click."] = "Fügt eine Taste „Alles erlernen“ neben der Taste „Erlernen“ bei Berufslehrern hinzu, sodass Ihr alle verfügbaren Fertigkeiten mit einem Klick erlernen könnt."
L["Adds a Calc toggle button to the character sheet that opens and closes the Upgrade Calculator."] = "Fügt dem Charakterfenster eine Taste für den Rechner hinzu, die den Aufwertungsrechner öffnet und schließt."
L["Adds a glowing, pulsating border around the Accept button of resurrection popups so a pending resurrect is hard to miss. Follows the Element & Text Color setting. Applies instantly, no reload needed."] = "Fügt der Annehmen Taste von Wiederbelebungsfenstern einen leuchtenden, pulsierenden Rahmen hinzu, damit eine ausstehende Wiederbelebung nicht übersehen wird. Verwendet die Einstellung für Element- und Textfarbe. Wird sofort ohne Neuladen angewendet."
L["Adds a mover for Blizzard's top-center event text and widgets (scenario, event, and encounter bars)."] = "Fügt einen Anker für Blizzards oben zentrierten Ereignistext und Widgets hinzu (Szenario-, Ereignis- und Bossbegegnungsleisten)."
L["Adds a Shadow border to your player frame when you pull or hold threat as a non-tank. Only active in dungeons, raids and delves."] = "Fügt Eurem Spielerfenster einen Schattenrand hinzu, wenn Ihr als Nicht Tank Bedrohung erzeugt oder haltet. Nur in Dungeons, Schlachtzügen und Tiefen aktiv."
L["Adds a steady red glow around the nameplate while the Near Aggro color is active."] = "Fügt ein stetiges rotes Leuchten um die Namensplakette hinzu, während die Farbe für 'Nahe Bedrohung' aktiv ist."
L["Adds a strip down the left edge of a loot toast in the item's quality color. The flat skin drops Blizzard's quality ring around the icon, so this puts that rarity cue back."] = "Fügt der linken Kante einer Beute Benachrichtigung einen Streifen in der Qualitätsspezifischen Farbe des Gegenstands hinzu. Das flache Design entfernt Blizzards Qualitätsring um das Symbol; diese Option stellt den Seltenheitshinweis wieder her."
L["Adds Bonus Roll, Group Loot, and Alert Toast movers to Unlock Mode."] = "Fügt Anker für Bonuswurf, Gruppenbeute und Benachrichtigungs Toasts zum Freischaltmodus hinzu."
L["Adds timestamps to system messages, loot, achievements, and addon messages, not just player chat."] = "Fügt Zeitstempel zu Systemnachrichten, Beute, Erfolgen und Addon Nachrichten hinzu, nicht nur zum Spieler Chat."
