L["Appends the spell or item ID to tooltips. The same setting as Global Settings > Developer."] = "Fügt Tooltips die Zauber- oder Gegenstands ID hinzu. Dieselbe Einstellung wie Globale Einstellungen > Entwickler."
L["Appends your latency in milliseconds to the cast timer, e.g. 1.8 (42ms)."] = "Fügt Eure Latenz in Millisekunden zum Zauberbalken hinzu, z. B. 1.8 (42ms)."
