L["Applies one text size to every chat window, saved with your profile. Individual windows can still be adjusted from their tab's right-click menu until the next login re-applies the profile size."] = "Wendet eine einheitliche Textgröße auf jedes Chatfenster an, gespeichert in Deinem Profil. Einzelne Fenster können weiterhin über das Rechtsklick-Menü ihres Reiter-Tabs angepasst werden, bis beim nächsten Login die Profilgröße erneut angewendet wird."
