L["Apply the sharer's Blizz UI Enhanced Window Skins and Tooltips, Menus & Popups settings. These are account-wide and will overwrite yours across ALL profiles. Off = keep your own."] = "Wendet die Einstellungen des Freigebenden für 'Erweitertes Blizzard-UI' (Fenster Skins sowie Tooltips, Menüs & Pop-ups) an. Diese gelten accountweit und überschreiben deine Einstellungen über ALLE Profile hinweg. Aus = Eigene behalten."
L["Apply the sharer's fonts, custom colours, dark mode, accent colour and UI scale. Off = keep your own global look and scale; only the selected modules' settings come in."] = "Übernimmt Schriftarten, benutzerdefinierte Farben, Dunkelmodus, Akzentfarbe und UI-Skalierung des Erstellers. Aus = Behält Dein eigenes globales Aussehen und Deine Skalierung bei; nur die Einstellungen der ausgewählten Module werden importiert."
L["Apply this pandemic glow to all CDM bars and tracking bars. A surface that can't show a style uses its closest match."] = "Wendet dieses Pandemie Leuchten auf alle CDM Leisten und Verfolgungsleisten an. Eine Oberfläche, die einen Stil nicht anzeigen kann, verwendet die am besten passende Alternative."
