L["Automatic follows the zone name. Manual holds the block at a fixed width and clips longer names, so it never shifts the blocks beside it."] = "Automatisch passt sich dem Zonennamen an. Manuell hält den Block auf einer festen Breite und schneidet längere Namen ab, sodass sich benachbarte Blöcke niemals verschieben."
L["Automatic shows XP while leveling and reputation at max level."] = "Automatisch zeigt EP während des Levelns und Ruf auf der Höchststufe an."
L["Automatic"] = "Automatisch"
L["Automatically dismisses the 'new mount/pet/toy' fanfare notification when you receive one, so you don't have to click through the collections journal."] = "Blendet die Fanfaren Benachrichtigung für ein „neues Reittier/Haustier/Spielzeug“ beim Erhalt automatisch aus, sodass Ihr Euch nicht durch das Sammlungsjournal klicken müsst."
L["Automatically duplicates the raid's tanks into the Extra Frames group. Shares the 5-frame cap with hotkey picks."] = "Dupliziert die Tanks des Schlachtzugs automatisch in die Gruppe „Extra-Fenster“. Teilt sich das Limit von maximal 5 Fenstern mit den Tastenkürzel Auswahlen."
L["Automatically enables the 'Current Expansion Only' filter whenever you open the Auction House."] = "Aktiviert automatisch den Filter „Nur aktuelle Erweiterung“, wenn das Auktionshaus geöffnet wird."
L["Automatically inserts your key into the Font of Power."] = "Setzt Euren Schlüsselstein automatisch in den Born der Macht ein."
L["Automatically opens and closes the Upgrade Calculator when the Character Sheet is opened or closed."] = "Öffnet und schließt den Aufwertungsrechner automatisch, wenn das Charakterfenster geöffnet oder geschlossen wird."
L["Automatically opens bags, boxes and parcels in your inventory when they are added to your bags.\n\nContainers received from the mailbox are held until you close the mailbox, so opening them cannot collide with mail still delivering items."] = "Öffnet Beutel, Kisten und Pakete in Deinem Inventar automatisch, sobald sie Deinen Taschen hinzugefügt werden.\n\nBehälter aus dem Briefkasten werden zurückgehalten, bis Du den Briefkasten schließt, damit das Öffnen nicht mit noch eingehender Post kollidiert."
L["Automatically opens the Upgrade Calculator when the Crest Upgrade NPC window is opened."] = "Öffnet den Aufwertungsrechner automatisch, wenn das Fenster des Wappen Aufwertungs NPCs geöffnet wird."
L["Automatically refreshes the Premade Groups list every few seconds while you are browsing, so newly posted groups appear without clicking Refresh."] = "Aktualisiert die Liste der organisierten Gruppen während des Durchstöberns alle paar Sekunden automatisch, sodass neu erstellte Gruppen ohne Klicken auf „Aktualisieren“ erscheinen."
L["Automatically removes cosmetic transforms when they are applied to you, such as profession gear, holiday costumes, toys and consumables. Use the cog to pick exactly which transforms are removed. Transforms applied during combat are removed when combat ends."] = "Entfernt automatisch kosmetische Verwandlungen, wenn sie auf dich angewendet werden, wie z. B. Berufsausrüstung, Feiertagskostüme, Spielzeuge und Verbrauchsgüter. Verwende das Zahnrad, um genau auszuwählen, welche Verwandlungen entfernt werden. Während des Kampfs angewendete Verwandlungen werden nach Kampfende entfernt."
L["Automatically repair all gear when visiting a repair vendor."] = "Repariert automatisch die gesamte Ausrüstung beim Besuch eines Reparaturhändlers."
L["Automatically sell all junk items when visiting a vendor."] = "Verkauft automatisch alle grauen Gegenstände beim Besuch eines Händlers."
L["Automatically Skip If Possible"]  = "Automatisch überspringen, wenn möglich"
L["Automatically starts and stops combat logging when entering or leaving a loggable instance."] = "Startet und stoppt das Kampf Loggen automatisch beim Betreten oder Verlassen einer dafür vorgesehenen Instanz."
L["Automatically types DELETE when throwing away a valuable item. Also allows you to press enter to accept the deletion."] = "Tippt automatisch „LÖSCHEN“ (bzw. „DELETE“), wenn ein wertvoller Gegenstand weggeworfen wird. Ermöglicht zudem das Bestätigen der Löschung per Eingabetaste."
L["Automatically zoom back out to maximum distance after this many seconds of no manual zoom change. 0 disables the reset."] = "Zoomt automatisch nach dieser Anzahl von Sekunden ohne manuelle Änderung wieder auf die maximale Entfernung heraus. 0 deaktiviert das Zurücksetzen."
L["Available only when Anchor to Windows is set to Free Move."] = "Nur verfügbar, wenn „An Fenstern verankern“ auf „Freie Bewegung“ eingestellt ist."
L["Avoidable Damage Taken"] = "Vermeidbarer Schaden erlitten"
