L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "Färbt den Gesundheitsbalken je nach verbleibender Gesundheit ein, anstatt eine einheitliche Farbe zu verwenden. 'Klassisch' verläuft von Grün bei voller Gesundheit über Gelb bis Rot bei leerer Gesundheit. 'Benutzerdefinierte Farben' geht fließend zwischen den drei Farbfeldern dieser Zeile über – voll (100%), halb (50%) und leer (0%). 'Klassenreaktiv' zeigt bei voller Gesundheit die Klassenfarbe und geht bei Erleiden von Schaden in die 50%- und 0% Farben über. 'Aus' überlässt die Steuerung den einheitlichen Füllfarbfeldern; der darunter liegende Farbverlauf wird in jedem Fall angewendet und geht von der hier gewählten Farbe aus."
