L["Colors group and raid member names by their class when they appear in the text of Say, Yell, Party, and Raid messages."] = "Färbt die Namen von Gruppen- und Schlachtzugsmitgliedern nach ihrer Klasse ein, wenn sie im Text von Sagen-, Schreien-, Gruppen- und Schlachtzugsnachrichten erscheinen."
