L["EllesmereUI Profile switched. Reload UI to apply?"] = "EllesmereUI Profil gewechselt. Interface neu laden, um es zu übernehmen?"
L["EllesmereUI Raid Frames are here! Clean, fully customizable, and built for performance."] = "Die EllesmereUI Schlachtzugsfenster sind da! Schlicht, vollständig anpassbar und auf Leistung ausgelegt."
L["EllesmereUI WonderBar was renamed to EllesmereUI DataBars. The old WonderBar addon is still installed and both create the same bar. Please disable or delete the EllesmereUIWonderBar addon."] = "EllesmereUI WonderBar wurde in EllesmereUI DataBars umbenannt. Das alte Addon WonderBar ist noch installiert und beide erstellen dieselbe Leiste. Bitte deaktiviere oder lösche das Addon EllesmereUIWonderBar."
