L["Flashes LOW MANA during an out-of-combat raid ready check while you are a healer under 80% mana."] = "Blinkt mit WENIG MANA während einer Bereitschaftsabfrage außerhalb des Kampfs, wenn du als Heiler unter 80% Mana hast."
