L["For player frame, this provides a simple, mini castbar below player frame. To edit the main player cast bar, %sclick here|r"] = "Für das Spielerfenster wird hierdurch eine einfache, kleine Zauberleiste unter dem Spielerfenster bereitgestellt. Um die Hauptzauberleiste des Spielers zu bearbeiten, %shier klicken|r"
L["For player frame, this provides a simple, mini castbar below player frame. To edit the main player cast bar, |cff0cd29dclick here|r"] = "Für das Spielerfenster wird hierdurch eine einfache, kleine Zauberleiste unter dem Spielerfenster bereitgestellt. Um die Hauptzauberleiste des Spielers zu bearbeiten, |cff0cd29dhier klicken|r"
L["For player frame, this provides a simple, mini castbar below player frame. To edit the main player cast bar, |cff9335d5click here|r"] = "Für das Spielerfenster wird hierdurch eine einfache, kleine Zauberleiste unter dem Spielerfenster bereitgestellt. Um die Hauptzauberleiste des Spielers zu bearbeiten, |cff9335d5hier klicken|r"
L["For tabs outside the chat panel, uses the chat panel's border style and color instead of separate tab border settings."] = "Verwendet für Reiter außerhalb des Chat-Fensters den Rahmenstil und die Farbe des Chat-Fensters anstelle separater Reiter Rahmeneinstellungen."
L["Forager's Medley"] = "Sammlermischung"
L["Force boss buffs into a single large column matched to the frame height."] = "Erzwingt Boss Stärkungszauber in eine einzige große Spalte, die an die Fensterhöhe angepasst ist."
L["Force boss debuffs into a single large column matched to the frame height (excluding cast bar), aligned to the chosen side of the frame. Overrides the Debuffs Location and Debuff Size settings while active. None disables it and uses the normal Debuffs Location."] = "Erzwingt Boss Schwächungszauber in eine einzige große Spalte, die an die Fensterhöhe (ohne Zauberleiste) angepasst und an der gewählten Fensterseite ausgerichtet ist. Überschreibt im aktiven Zustand die Einstellungen für Platzierung und Größe der Schwächungszauber. „Keine“ deaktiviert dies und verwendet die normale Platzierung."
L["Force boss debuffs into a single large column matched to the frame height."] = "Erzwingt Boss Schwächungszauber in eine einzige große Spalte, die an die Fensterhöhe angepasst ist."
L["Force Centered"] = "Zentrierung erzwingen"
L["Force Chat on Screen"] = "Chat auf dem Bildschirm erzwingen"
L["Force debuffs to the Left of the frame and size them to match the frame height (excluding cast bar). Overrides the Debuffs Location and debuff size settings while enabled."] = "Erzwingt Schwächungszauber auf die linke Seite des Fensters und passt ihre Größe an die Fensterhöhe (ohne Zauberleiste) an. Überschreibt im aktivierten Zustand die Einstellungen für Platzierung und Größe der Schwächungszauber."
L["Force garbage collection"] = "Müllsammlung erzwingen"
L["Force of Nature\n(Cursor)"] = "Treants\n(Mauszeiger)"
L["Force Quest Tracker on Screen"] = "Questverfolgung auf dem Bildschirm erzwingen"
L["Force-hide Blizzard's Assisted Combat Highlight (rotation helper glow) on all CDM bars, even if enabled in Blizzard's Combat settings."] = "Erzwingt das Ausblenden von Blizzards Hervorhebung für unterstützten Kampf (Leuchten der Rotationshilfe) auf allen CDM Leisten, selbst wenn es in den Blizzard-Kampfeinstellungen aktiviert ist."
L["Forces a crisp outline on icon text (stack counts, durations, keybinds). Uncheck a module to make its icon text follow the Outline Mode setting above instead."] = "Erzwingt eine scharfe Kontur auf Symboltexten (Stapelanzahl, Dauer, Tastenbelegungen). Deaktiviert ein Modul, damit dessen Symboltext stattdessen der obigen Einstellung für den Konturmodus folgt."
L["Forces all casts to be shown in front of nameplates for visual clarity"] = "Erzwingt zur visuellen Klarheit die Anzeige aller Zauber vor den Namensplaketten"
L["Forces which way the default screen-anchored tooltip expands as lines are added. Default lets Blizzard decide from the tooltip's screen position."] = "Erzwingt die Richtung, in die der am Bildschirm verankerte Tooltip wächst, wenn Zeilen hinzukommen. Standard lässt Blizzard anhand der Bildschirmposition entscheiden."
