L["Hide targeted spells on preview"] = "Gezielte Zauber in Vorschau ausblenden"
L["Hide the brief GCD swipe that flashes when you cast any spell. The actual ability cooldown swipe still shows."] = "Blendet den kurzen GCD Wischeffekt aus, der beim Wirken eines Zaubers aufblinkt. Der eigentliche Abklingzeit Wischeffekt der Fähigkeit wird weiterhin angezeigt."
L["Hide the charge number on action buttons when it reaches 0, instead of showing a 0. The number returns as soon as a charge or item comes back."] = "Blendet die Aufladungsanzahl auf Aktionsleistentasten aus, wenn sie 0 erreicht, anstatt eine 0 anzuzeigen. Die Zahl erscheint wieder, sobald eine Aufladung oder ein Gegenstand verfügbar ist."
L["Hide the charge number while a spell has no charges left, instead of showing a 0. The number returns as soon as a charge comes back."] = "Blendet die Anzahl der Aufladungen aus, solange ein Zauber keine Aufladungen mehr hat, anstatt eine 0 anzuzeigen. Die Zahl erscheint wieder, sobald eine Aufladung verfügbar ist."
L["Hide the enemy name text while that nameplate's cast bar is visible."] = "Blendet den Gegnernamen aus, während die Zauberleiste dieser Namensplakette sichtbar ist."
L["Hide the icon texture, border, and duration swipe, leaving only the stack count. Forces icon opacity, border, and duration swipe off."] = "Blendet die Symboltextur, den Rahmen und den Dauer-Wischeffekt aus, sodass nur die Stapelanzahl übrig bleibt. Erzwingt das Deaktivieren von Symboldeckkraft, Rahmen und Dauer-Wischeffekt."
L["Hide the preview"] = "Vorschau ausblenden"
L["Hide the randomize (dice) button in the OneBag view."] = "Blendet die Zufallstaste (Würfel) in der Einzeltasche Ansicht aus."
L["Hide the Reset Data button from the damage meter header."] = "Blendet die Taste „Daten zurücksetzen“ aus der Kopfzeile des Schadensmeters aus."
L["Hide the warning text at the top of the OneBag and MultiBag views."] = "Blendet den Warntext am oberen Rand der Einzeltasche- und Mehrfachtasche Ansichten aus."
L["Hide the warning text at the top of the OneBag view."] = "Blendet den Warntext am oberen Rand der Einzeltasche Ansicht aus."
L["Hide these instead of showing them"] = "Diese ausblenden, anstatt sie anzuzeigen"
L["Hide this bar completely while out of combat, even when the tracked buff/cooldown is active."] = "Diese Leiste außerhalb des Kampfes vollständig ausblenden, auch wenn der verfolgte Stärkungszauber bzw. die Abklingzeit aktiv ist."
L["Hide this bar's icon art, cooldown swipe, recharge edge and cooldown text, leaving only the charge or stack count."] = "Blendet Symbolgrafik, Abklingzeit Animation, Aufladekante und Abklingzeit-Text dieser Leiste aus, sodass nur die Aufladungs- oder Stapelanzahl übrig bleibt."
L["Hide this bar's icons and show only the duration text."] = "Blendet die Symbole dieser Leiste aus und zeigt nur den Dauertext an."
L["Hide Timer"] = "Timer ausblenden"
