L["Hide Top Bar"] = "Obere Leiste ausblenden"
L["Hide Tutorial Pop-ups"] = "Tutorial Popups ausblenden"
L["Hide Unit Health Strip"] = "Gesundheitsbalken der Einheit ausblenden"
L["Hide Unlock Mode Menu Button"] = "Menütaste für Freischaltungsmodus ausblenden"
L["Hide Unlock Mode Overlay"] = "Freischaltmodus Overlay ausblenden"
L["Hide Unlock Mode Overlays"] = "Freischaltmodus-Overlays ausblenden"
L["Hide Unusable Entries"] = "Unbenutzbare Einträge ausblenden"
L["Hide When Idle"] = "Bei Inaktivität ausblenden"
