L["Hide without Target"] = "Ohne Ziel ausblenden"
L["Hide"] = "Ausblenden"
L["Hides Blizzard's \"Loot Rolls\" window -- the running list of dropped items showing who rolled what and who won. Use the cog to let it appear briefly and close itself instead. The Need/Greed roll popups themselves are not affected."] = "Blendet Blizzards 'Beutewürfe'-Fenster aus – die fortlaufende Liste der erbeuteten Gegenstände, die anzeigt, wer was gewürfelt und wer gewonnen hat. Nutze das Zahnrad, um es stattdessen kurz erscheinen und sich selbst schließen zu lassen. Die Bedarf/Gier-Würfel-Popups selbst sind nicht betroffen."
L["Hides Blizzard's own micro menu while any bar has this on."] = "Blendet Blizzards eigenes Mikromenü aus, wenn dies auf einer Leiste aktiv ist."
L["Hides Blizzard's tutorial UI: the yellow HelpTip bubbles and the glowing (i) help-plate buttons on the spellbook, talents, map, collections, and other panels."] = "Blendet Blizzards Tutorial-UI aus: die gelben Hilfetipp-Blasen und die leuchtenden (i)-Hilfetasten im Zauberbuch, den Talenten, der Karte, den Sammlungen und anderen Fenstern."
L["Hides most red error messages (such as 'Not enough rage' or 'Ability is not ready yet'). Important errors like a full bag or quest log are still shown."] = "Blendet die meisten roten Fehlermeldungen aus (wie „Nicht genug Wut“ oder „Fähigkeit ist noch nicht bereit“). Wichtige Fehler wie eine volle Tasche oder ein volles Questlog werden weiterhin angezeigt."
L["Hides Pinned Items. Re-show in settings."] = "Blendet angepinnte Gegenstände aus. In den Einstellungen wieder einblenden."
L["Hides Recent Items. Re-show in settings."] = "Hinterlegt kürzlich verwendete Gegenstände aus. In den Einstellungen wieder einblenden."
L["Hides the 'Screenshot saved' notification that appears on screen after taking a screenshot."] = "Blendet die Benachrichtigung „Screenshot gespeichert“ aus, die nach dem Erstellen eines Screenshots auf dem Bildschirm erscheint."
L["Hides the Add Category button at the bottom of the bag sidebar."] = "Blendet die Taste „Kategorie hinzufügen“ unten in der Taschen Seitenleiste aus."
L["Hides the collapsed Blizzard party/raid sidebar panel on the side of the screen."] = "Blendet das eingeklappte Blizzard Gruppen-/Schlachtzugs Seitenleistenfenster am Bildschirmrand aus."
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "Blendet die EllesmereUI Taste aus dem Escape-/Pausenmenü des Spiels aus."
L["Hides the health bar Blizzard shows at the bottom of unit tooltips."] = "Blendet die Gesundheitsleiste aus, die Blizzard unten in den Einheiten Tooltips anzeigt."
L["Hides the large NPC dialogue popup that appears during quests and dungeons."] = "Blendet das große NPC-Dialogfenster aus, das während Quests und Dungeons erscheint."
L["Hides the Lua error popup. The same setting as Global Settings > Developer."] = "Blendet das Lua-Fehler-Popup aus. Dieselbe Einstellung wie Globale Einstellungen > Entwickler."
L["Hides the master header and its minimize button at the top of the tracker. When shown, it's skinned to match the section headers below it (Quests, Achievements, ...)."] = "Blendet die Hauptkopfzeile und deren Taste zum Minimieren oben im Tracker aus. Wenn sie angezeigt wird, ist ihr Skin an die darunter liegenden Abschnitte (Quests, Erfolge, ...) angepasst."
L["Hides the rank number (1. 2. 3.) before each player name."] = "Blendet die Rangnummer (1. 2. 3.) vor jedem Spielernamen aus."
L["Hides the ready check glyph above the prompt, leaving just the question and the Yes / No buttons. Applies while the Ready Check reskin is enabled."] = "Blendet das Bereitschaftsabfrage-Symbol über der Aufforderung aus, sodass nur die Frage und die Tasten 'Ja' / 'Nein' übrig bleiben. Gilt, während der Skin für die Bereitschaftsabfrage aktiviert ist."
L["Hides the resize handle on the main chat frame, preventing accidental resizing."] = "Blendet den Ziehpunkt zur Größenänderung am Hauptchatfenster aus, um versehentliches Ändern der Größe zu verhindern."
L["Hides the sync icons on the sidebar module list."] = "Blendet die Synchronisationssymbole in der Modulliste der Seitenleiste aus."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "Blendet die Taste für den Freischaltungsmodus aus dem Escape-/Pausenmenü des Spiels aus. Ihr könnt den Freischaltungsmodus weiterhin über das EUI Konfigurationsmenü umschalten."
