L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire. Build up to 16 menus in Arc, Fan, or Grid layouts, nest menus inside menus, and tune every setting per menu."] = "Halte eine Tastenbelegung gedrückt, um ein Aktionen Menü zu öffnen; zeige oder scrolle zum Auswählen, lasse los zum Ausführen. Erstelle bis zu 16 Menüs in Bogen-, Fächer- oder Raster-Layouts, verschachtele Menüs ineinander und passe jede Einstellung pro Menü individuell an."
