L["Include CDM Spell Layout?"] = "CDM Zauberlayout einschließen?"
L["Include fonts, custom colours, dark mode, accent colour and UI scale with this export. Off = only the selected modules' own settings export, keeping the recipient's global look."] = "Schließe Schriftarten, benutzerdefinierte Farben, Dunkelmodus, Akzentfarbe und UI-Skalierung in diesen Export ein. Aus = Nur die eigenen Einstellungen der ausgewählten Module werden exportiert, wodurch das globale Erscheinungsbild des Empfängers erhalten bleibt."
L["Include Headerbar"] = "Kopfzeile einschließen"
L["Include layout"] = "Layout einschließen"
L["Include the anchor & size-match relationships between modules. Off = export each module's own positions only, with no cross-module tying."] = "Schließt die Beziehungen für Verankerung und Größenanpassung zwischen den Modulen ein. Aus = Exportiert nur die eigenen Positionen jedes Moduls, ohne modulübergreifende Verknüpfung."
L["Include Window Skins"] = "Fenster Skins einschließen"
L["Include your Blizz UI Enhanced settings from the Window Skins and Tooltips, Menus & Popups tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "Enthält deine 'Erweitertes Blizzard-UI' Einstellungen aus den Reitern 'Fenster Skins' sowie 'Tooltips, Menüs & Pop-ups'. Diese gelten accountweit: Stimmt der Importeur zu, überschreiben sie dessen Einstellungen über ALL seine Profile hinweg."
L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "Enthält dein komplettes Überschreibungs-Setup: Spezialisierungs- und bedingte Überschreibungswerte, Gruppen, deren benutzerdefinierte Freischaltmodus-Layouts sowie Stärkungszauber Manager-Überschreibungen. Beim Import ersetzt dies die Überschreibungen des Empfängers vollständig."
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "Schließt Euer Cooldown Manager Zauberlayout ein (welche Zauber auf welchen Leisten liegen) sowie alle zauberspezifischen Einstellungen für alle von Euch gewählten Spezialisierungen."
