L["Keep Action Bar 1 on its current page when you shapeshift, stealth, or change stance, instead of swapping to that form's bar.\n\nKeybinds follow what the bar shows, so the key always casts the icon you see. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Behält Aktionsleiste 1 auf Deiner aktuellen Seite, wenn Du Deine Gestalt wandelst, Dich verstiehlst oder Deine Haltung wechselst, anstatt zur Leiste dieser Gestalt zu wechseln.\n\nTastenbelegungen folgen der Anzeige der Leiste, sodass die Taste immer den Zauber des angezeigten Symbols wirkt. Das Wiederholen von Zaubern durch Drücken-und-Halten ist auf Aktionsleiste 1 deaktiviert, solange diese Option aktiv ist."
L["Keep Action Bar 1 on its current page while skyriding, instead of swapping to the skyriding bar.\n\nYour skyriding abilities live on that bar, so put them on another bar before enabling this. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Behält Aktionsleiste 1 beim Himmelsreiten auf Deiner aktuellen Seite, anstatt zur Himmelsreiten-Leiste zu wechseln.\n\nDeine Himmelsreiten-Fähigkeiten liegen auf dieser Leiste; platziere sie daher auf einer anderen Leiste, bevor Du diese Option aktivierst. Das Wiederholen von Zaubern durch Drücken-und-Halten ist auf Aktionsleiste 1 deaktiviert, solange diese Option aktiv ist."
L["Keep Buffs in Same Place"] = "Stärkungszauber am selben Ort halten"
L["Keep Colored (On CD)"] = "Farbig lassen (bei Abklingzeit)"
L["Keep Enabled"] = "Aktiviert lassen"
L["Keep Focus Full Opacity"] = "Fokus voll deckend lassen"
L["Keep keybind text identical when your action bar swaps -- rogue stealth, druid forms, skyriding. Also covers conditional macros like \"/cast [bonusbar:1] Backstab; Shadow Dance\", where the key would otherwise jump to whichever branch is live.\n\nThe key then only changes when you actually move the ability or rebind it.\n\nOn by default. Applies to every CDM bar at once."] = "Hält den Text der Tastenbelegungen identisch, wenn Deine Aktionsleiste wechselt – Schurken-Tarnung, Druidengestalten, Himmelsreiten. Deckt auch bedingte Makros wie \"/cast [bonusbar:1] Hinterhalt; Schattentanz\" ab, bei denen die Taste sonst zu dem jeweils aktiven Zweig springen würde.\n\nDie Taste ändert sich dann nur, wenn Du die Fähigkeit tatsächlich verschiebst oder neu belegst.\n\nStandardmäßig aktiviert. Gilt für alle CDM Leisten gleichzeitig."
L["Keep Keys on Bar Swap (global)"] = "Tasten bei Leistenwechsel beibehalten (global)"
L["Keep Raid Frames"] = "Schlachtzugsfenster behalten" 
L["Keep the GCD bar visible (sitting empty) when no global cooldown is running, instead of hiding it."] = "Hält die GCD Leiste sichtbar (leer verbleibend), wenn keine globale Abklingzeit läuft, anstatt sie auszublenden."
L["Keep the timer visible out of combat, showing the last fight's duration."] = "Hält den Timer außerhalb des Kampfes sichtbar und zeigt die Dauer des letzten Kampfes an."
L["Keep this menu open when you let go of its keybind.\nPoint at an entry and press the Select Action key to use it.\nPress the menu's own keybind again, or Escape, to close it."] = "Hält dieses Menü geöffnet, wenn Du die Tastenbelegung loslässt.\nZeige auf einen Eintrag und drücke die Taste 'Aktion auswählen', um ihn zu nutzen.\nDrücke die eigene Tastenbelegung des Menüs erneut oder Escape, um es zu schließen."
L["Keep"] = "Behalten"
L["Keeps Blizzard's own buff and debuff display and turns off the built-in Buffs and Debuffs bars. Custom bars keep working."] = "Behält Blizzards eigene Anzeige für Stärkungs- und Schwächungszauber bei und schaltet die integrierten Leisten dafür aus. Eigene Leisten funktionieren weiterhin."
L["Keeps your note text in the Sign Up dialog instead of clearing it each time you open it."] = "Behält Euren Notiztext im Anmeldedialog bei, anstatt ihn jedes Mal beim Öffnen zu löschen."
