L["Make friendly player and NPC nameplates click-through so their names never block your mouse or cause accidental friendly targeting.\n\nUse this when friendly names get in the way of clicking the world or the enemy nameplates behind them."] = "Macht Namensplaketten von freundlichen Spielern und NPCs klickbar durchlässig, sodass ihre Namen niemals Eure Maus blockieren oder zu versehentlichem Anvisieren von Verbündeten führen.\n\nNutzt dies, wenn freundliche Namen das Klicken in der Welt oder auf die gegnerischen Namensplaketten dahinter behindern."
