L["Makes partially filled Soul Shards and Essence darker than completed ones."] = "Macht teilweise gefüllte Seelenfragmente und Essenz dunkler als vollständig gefüllte."
L["Makes the boss frames taller or shorter relative to the raid frame size."] = "Macht die Bossfenster im Verhältnis zur Größe des Schlachtzugsfensters höher oder kürzer."
L["Makes the extra frames taller or shorter relative to the raid frame size."] = "Macht die Extra-Fenster im Verhältnis zur Größe des Schlachtzugsfensters höher oder kürzer."
L["Makes the game tooltip follow your mouse cursor instead of showing at its fixed screen position (drag the Tooltip box in Unlock Mode to change that). Use the arrows icon to pick the position relative to the cursor and fine-tune the X/Y offset."] = "Bewirkt, dass der Spiel-Tooltip deinem Mauszeiger folgt, anstatt an seiner festen Bildschirmposition zu erscheinen (ziehe das Tooltip-Fenster im Freischaltmodus, um dies zu ändern). Nutze das Pfeilsymbol, um die Position relativ zum Cursor zu wählen und den X/Y-Versatz feinzujustieren."
