L["On quest mobs in the open world, replaces the quest icon with the objective progress (a kill quest shows 0/6, a percentage quest shows 50%). Falls back to the icon when no progress is available. Never shown in instances."] = "Ersetzt bei Quest Mobs in der offenen Welt das Questsymbol durch den Zielfortschritt (eine Tötungsquest zeigt 0/6, eine Prozentquest zeigt 50%). Fällt auf das Symbol zurück, wenn kein Fortschritt verfügbar ist. Wird niemals in Instanzen angezeigt."
