L["One video walks you through the most important changes in 12.1 and how to get the most out of EllesmereUI under them. Copy the link and give it a watch before you dive in."] = "Ein Video führt Dich durch die wichtigsten Änderungen in 12.1 und zeigt Dir, wie Du EllesmereUI optimal dafür nutzt. Kopiere den Link und schau es Dir an, bevor Du loslegst."
L["One Window combines everything into a single element; the Only choices show just that part."] = "'Ein Fenster' fasst alles in einem einzigen Element zusammen; die 'Nur' Optionen zeigen nur den jeweiligen Teil an."
