L["One-time copy of the Raid Frames Buff Manager filters into these filters. Same-named filters are OVERWRITTEN; the two lists stay separate afterwards."] = "Einmaliges Kopieren der Filter aus dem Stärkungszauber Manager der Schlachtzugsfenster in diese Filter. Gleichnamige Filter werden ÜBERSCHRIEBEN; beide Listen bleiben danach getrennt."
L["One-time copy of your Player Aura Bars filter setups into these filters. Same-named filters are OVERWRITTEN; the two lists stay separate afterwards."] = "Einmaliges Kopieren Deiner Filterkonfigurationen der Spieler Aurenleisten in diese Filter. Gleichnamige Filter werden ÜBERSCHRIEBEN; beide Listen bleiben danach getrennt."
