L["Online"] = "Online"
L["Only available in Detached or Inside modes"] = "Nur im losgelösten oder inneren Modus verfügbar"
L["Only available with Custom fill color"] = "Nur mit benutzerdefinierter Füllfarbe verfügbar"
L["Only available with the 'From' direction -- it highlights the pips at/above the threshold."] = "Nur mit der Richtungsoption 'Von' verfügbar – hebt die Punkte hervor, die am oder über dem Schwellenwert liegen."
L["Only Cast on Actual Units (Not Frames)"] = "Nur auf tatsächliche Einheiten wirken (nicht auf Fenster)"
L["Only Cast Out of Combat"] = "Nur außerhalb des Kampfes wirken"
L["Only Color At/Above Threshold"] = "Nur bei/über Schwellenwert einfärben"
L["Only Dispellable by You"] = "Nur von dir bannbar"
L["Only Group & Pull"] = "Nur Gruppe & Pull"
L["Only Hide Fully Synced"] = "Nur vollständig Synchronisierte ausblenden"
L["Only In Combat"] = "Nur im Kampf"
L["Only Instant Casts"] = "Nur Spontanzauber"
L["Only Markers"] = "Nur Markierungen"
L["Only Open Menu Out of Combat"] = "Menü nur außerhalb des Kampfes öffnen"
L["Only preset or custom buff bars can be added to all specs"] = "Nur vordefinierte oder benutzerdefinierte Stärkungszauberleisten können für alle Spezialisierungen hinzugefügt werden"
L["Only show buffs cast by you."] = "Nur von Dir gewirkte Stärkungszauber anzeigen."
L["Only show debuffs that have a duration, excluding permanent ones. Combines with the filters below; checked alone it shows every timed debuff."] = "Zeigt nur Schwächungszauber mit einer Dauer an und schließt dauerhafte aus. Lässt sich mit den darunter liegenden Filtern kombinieren; allein aktiviert zeigt es jeden zeitlich begrenzten Schwächungszauber."
L["Only Show Dispellable"] = "Nur Bannbare anzeigen"
L["Only Show in Housing"] = "Nur im Housing anzeigen"
L["Only Show in Instances"] = "Nur in Instanzen anzeigen"
L["Only Show Numbers"] = "Nur Zahlen anzeigen"
L["Only show the alert while in combat."] = "Die Warnung nur anzeigen, während du dich im Kampf befindest."
L["Only show the GCD bar for instant-cast abilities. While hard-casting or channeling a spell, the bar stays hidden (the cast bar already shows that progress)."] = "GCD Leiste nur für Spontanzauber anzeigen. Während eines Zaubers oder einer Kanalisierung bleibt die Leiste ausgeblendet (die Zauberleiste zeigt diesen Fortschritt bereits an)."
L["Only show the GCD bar while in a dungeon, raid, arena or battleground."] = "GCD Leiste nur in Dungeons, Schlachtzügen, Arenen oder Schlachtfeldern anzeigen."
L["Only show this bar while the tracked buff/cooldown is active. Turn off to keep an empty bar on screen at all times."] = "Diese Leiste nur anzeigen, wenn der verfolgte Stärkungszauber/Abklingzeit aktiv ist. Deaktivieren, um dauerhaft eine leere Leiste auf dem Bildschirm zu behalten."
L["Only show this bar while the tracked buff/cooldown is active. Unchecked keeps an empty bar on screen at all times."] = "Zeigt diese Leiste nur an, solange der verfolgte Stärkungszauber/die Abklingzeit aktiv ist. Deaktivieren, um jederzeit eine leere Leiste auf dem Bildschirm zu behalten."
L["Only Show When Hidden"] = "Nur anzeigen, wenn ausgeblendet"
L["Only Show when Mounted"] = "Nur auf Reittieren anzeigen"
L["Only shows the cursor circle while the mouse is hidden -- that is, while you hold the left and/or right mouse button to pan the camera or move your character."] = "Zeigt den Cursor Kreis nur an, während die Maus ausgeblendet ist – das heißt, wenn Ihr die linke und/oder rechte Maustaste gedrückt haltet, um die Kamera zu drehen oder Euren Charakter zu bewegen."
