L["Remembers the Tank/Healer/DPS roles you last applied with and restores them the next time you sign up to a premade group (limited to roles your current spec can fill). Works with or without the reskin."] = "Merkt sich die Tank/Heiler/DPS-Rollen, mit denen Du Dich zuletzt beworben hast, und stellt sie wieder her, wenn Du Dich das nächste Mal für eine organisierte Gruppe anmeldest (beschränkt auf Rollen, die Deine aktuelle Spezialisierung ausfüllen kann). Funktioniert mit und ohne Neugestaltung."
L["Remind you to grab a Healthstone when a Warlock is in your group."] = "Erinnert Euch daran, einen Gesundheitsstein zu nehmen, wenn sich ein Hexenmeister in Eurer Gruppe befindet."
L["Reminder Sound"] = "Erinnerungssound"
L["Reminder threshold while you are in a dungeon before a Mythic+ key starts (Mythic 0 / keystone lobby). Set it high enough that you top up buffs and food before pulling, so you begin the key with enough duration to last it.\n0 = only when fully expired.\nIgnored once the key is active or you are in combat (then only when the buff is fully gone)."] = "Erinnerungsschwellenwert, während Du Dich vor dem Start eines Mythisch+-Schlüsselsteins in einem Dungeon befindest (Mythisch 0 / Schlüsselstein-Lobby). Stelle ihn hoch genug ein, um Stärkungszauber und Essen vor dem ersten Pull aufzufrischen, damit die Dauer für den gesamten Schlüsselstein ausreicht.\n0 = nur wenn vollständig abgelaufen.\nWird ignoriert, sobald der Schlüsselstein aktiv ist oder Du Dich im Kampf befindest (dann nur, wenn der Stärkungszauber vollständig abgelaufen ist)."
L["Reminders are always hidden in rested areas (cities and inns)."] = "Erinnerungen sind in Ruhebereichen (Städten und Gasthäusern) immer ausgeblendet."
