L["Reskins Blizzard tooltips with a dark, minimal style matching the EUI aesthetic. Requires reload to apply."] = "Skinnt Blizzard-Tooltips mit einem dunklen, minimalistischen Stil neu, der zur EUI Ästhetik passt. Erfordert ein UI Neuladen."
L["Reskins Blizzard tooltips, right-click context menus, and popups with a dark, minimal style matching the EUI aesthetic. Requires reload to apply."] = "Skinnt Blizzard Tooltips, Rechtsklick Kontextmenüs und Popups mit einem dunklen, minimalistischen Stil neu, der zur EUI Ästhetik passt. Erfordert ein UI Neuladen."
L["Reskins Blizzard's right-click context menus and pop-up dialogs with the EUI dark style. Requires reload to apply."] = "Skinnt Blizzards Rechtsklick Kontextmenüs und Popup Dialoge mit dem dunklen EUI Stil neu. Erfordert ein UI Neuladen."
L["Reskins the dungeon and battleground queue accept popups with the EUI dark style, and adds an accept countdown timer bar to the dungeon one."] = "Passt die Annahme-Popups für Dungeon- und Schlachtfeld-Warteschlangen im dunklen EUI Stil an und fügt beim Dungeon-Popup eine Leiste mit Annahme-Countdown hinzu."
L["Reskins the ESC / Game Menu with the EUI dark style, matching fonts, and accent-colored title."] = "Skinnt das ESC- / Spielmenü mit dem dunklen EUI Stil, passenden Schriftarten und einem Titel in Akzentfarbe neu."
L["Reskins the Great Vault window with custom tile backgrounds, progress colors, and completion states."] = "Skinnt das Fenster der Großen Schatzkammer mit benutzerdefinierten Kachelhintergründen, Fortschrittsfarben und Abschlussstatus neu."
L["Reskins the Group Finder / Premade Groups window with the EUI dark style."] = "Skinnt das Fenster für die Gruppensuche / Organisierte Gruppen mit dem dunklen EUI Stil neu."
L["Reskins the LFG/dungeon queue accept popup with the EUI dark style and adds an accept countdown timer bar."] = "Skinnt das Bestätigungs Popup der Dungeonsuche mit dem dunklen EUI Stil neu und fügt eine Countdown Leiste hinzu."
