L["Show copies of the same item that sit in separate bag slots as one icon with their counts added together. Turn this off to keep every slot separate, for example when you deliberately split stacks. Merging is always paused while the mail, trade, auction house, bank or guild bank window is open, since those take one bag slot at a time."] = "Zeigt Mehrfachexemplare desselben Gegenstands, die auf verschiedenen Taschenplätzen liegen, als ein einziges Symbol mit zusammengefasster Anzahl an. Deaktiviere dies, um jeden Platz einzeln zu lassen – zum Beispiel, wenn Du Stapel bewusst aufteilst. Die Zusammenführung wird automatisch pausiert, solange das Post-, Handels-, Auktionshaus-, Bank- oder Gildenbank-Fenster geöffnet ist, da diese nur jeweils einen einzelnen Taschenplatz verarbeiten."
