L["Show every buff that has a duration (hides permanent buffs). Use the Hide lane below to remove specific filters."] = "Zeigt jeden Stärkungszauber an, der eine Dauer hat (blendet dauerhafte Zauber aus). Nutze die Ausblenden-Zeile unten, um bestimmte Filter zu entfernen."
L["Show every buff that has a duration (hides permanent buffs). While this is on, checked filters below are hidden instead of added."] = "Zeigt jeden Stärkungszauber mit einer Dauer an (blendet dauerhafte Stärkungszauber aus). Während dies aktiv ist, werden unten ausgewählte Filter ausgeblendet, anstatt hinzugefügt zu werden."
L["Show every buff. Use the Hide lane below to remove specific filters."] = "Zeigt jeden Stärkungszauber an. Nutze die Ausblenden-Zeile unten, um bestimmte Filter zu entfernen."
L["Show every buff. While this is on, checked filters below are hidden from the bar instead of added."] = "Zeigt jeden Stärkungszauber an. Während dies aktiv ist, werden unten ausgewählte Filter von der Leiste ausgeblendet, anstatt hinzugefügt zu werden."
L["Show every buff. While this is on, checked filters below are hidden from the frame instead of added."] = "Zeigt jeden Stärkungszauber an. Während dies aktiv ist, werden unten ausgewählte Filter vom Fenster ausgeblendet, anstatt hinzugefügt zu werden."
L["Show every debuff in this indicator. Use the Hide lane below to remove specific filters."] = "Zeigt jeden Schwächungszauber in diesem Indikator an. Nutze die Ausblenden Zeile unten, um bestimmte Filter zu entfernen."
L["Show every debuff. Use the Hide lane below to remove specific filters."] = "Zeigt jeden Schwächungszauber an. Nutze die Ausblenden Zeile unten, um bestimmte Filter zu entfernen."
L["Show every debuff. While this is on, checked filters below are hidden from the bar instead of added."] = "Zeigt jeden Schwächungszauber an. Während dies aktiv ist, werden unten ausgewählte Filter von der Leiste ausgeblendet, anstatt hinzugefügt zu werden."
L["Show every debuff. While this is on, checked filters below are hidden from the frame instead of added."] = "Zeigt jeden Schwächungszauber an. Während dies aktiv ist, werden unten ausgewählte Filter vom Fenster ausgeblendet, anstatt hinzugefügt zu werden."
L["Show every debuff. While this is on, checked filters below are hidden from the grid instead of added."] = "Zeigt jeden Schwächungszauber an. Während dies aktiv ist, werden unten ausgewählte Filter vom Raster ausgeblendet, anstatt hinzugefügt zu werden."
