L["Show one plain cast bar per enemy nameplate that is casting, gathered into a single movable group with the spell name, its target, and the cast timer."] = "Zeigt eine einfache Zauberleiste pro zaubernder feindlicher Namensplakette an, zusammengefasst in einer einzigen verschiebbaren Gruppe mit Zaubernamen, Ziel und Zauber Timer."
L["Show one sub-category per equipment set (named after the set) nested under Item Set Gear. Gear in several sets goes to the first one."] = "Zeigt eine Unterkategorie pro Ausrüstungsset (benannt nach dem Set) unter 'Set-Ausrüstung' an. Ausrüstung in mehreren Sets wird dem ersten zugeordnet."
L["Show one-time video guide badges next to new or complex features. Each badge disappears forever once clicked."] = "Zeigt spezielle Video-Guide Plaketten neben neuen oder komplexen Funktionen an. Jedes Plakette verschwindet dauerhaft, sobald es angeklickt wird."
L["Show only while in a dungeon, raid, arena or battleground. Combine with Combat to show only during instanced combat."] = "Nur in einem Dungeon, Schlachtzug, einer Arena oder auf einem Schlachtfeld anzeigen. Mit 'Kampf' kombinieren, um es nur während eines instanziierten Kampfes anzuzeigen."
