L["Show reminders when remaining buff time is below this many minutes.\n0 = only when fully expired.\nIgnored in combat and during Mythic+ keys (then only when the buff is gone)."] = "Zeigt Erinnerungen an, wenn die verbleibende Stärkungszauber-Dauer unter dieser Anzahl von Minuten liegt.\n0 = nur wenn vollständig abgelaufen.\nWird im Kampf und während Mythisch+-Schlüsselsteinen ignoriert (dann nur, wenn der Stärkungszauber ganz weg ist)."
