L["Size of addon minimap buttons in the flyout grid"] = "Größe der Addon-Minimap-Buttons im Flyout-Raster"
L["Size of mail, calendar, tracking, and minimap button group toggle"] = "Größe des Umschalt-Buttons für Post, Kalender, Aufspüren und Minimap Gruppe"
L["Size of the bar across its block axis in pixels."] = "Größe der Leiste quer zu ihrer Blockachse in Pixeln."
L["Size of the bar along its block axis in pixels."] = "Größe der Leiste entlang ihrer Blockachse in Pixeln."
L["Size Offset"] = "Größenversatz"
L["Size"] = "Größe"
L["Sizes the bar to the full screen extent along its axis."] = "Größe der Leiste auf die volle Bildschirmlänge entlang ihrer Achse anpassen."
L["Skinning"] = "Kürschnerei"
L["Skip Cinematics"] = "Cinematics überspringen"
L["Skipped"] = "Übersprungen"
L["Skips your own frame when Show Tanks duplicates the raid's tanks. Hotkey picks can still add you."] = "Überspringt Dein eigenes Fenster, wenn 'Tanks anzeigen' die Tanks des Schlachtzugs dupliziert. Über Hotkey-Auswahlen kannst Du Dich weiterhin hinzufügen."
L["Skull Bash\n(Focus)"] = "Schädelstoß\n(Fokus)"
L["Skyfury"] = "Himmelszorn"
L["Skyreach"] = "Himmelsnadel"
L["Skyriding Bar Color"] = "Farbe der Himmelsreiten Leiste"
L["Skyriding Bar Height"] = "Höhe der Himmelsreiten Leiste"
L["Skyriding Bar"] = "Himmelsreiten Leiste"
L["Skyriding HUD with speed, vigor and second wind tracking."] = "Himmelsreiten HUD mit Verfolgung von Geschwindigkeit, Elan und Zweitem Wind."
L["Slayer's Rise"] = "Hügel der Jäger"
L["Slide In"] = "Eingleiten"
L["Slot Groups"] = "Platz Gruppen"
L["Slowly orbits your action bar buttons around each bar's centre while Party Mode is active. The buttons stay upright, so clicking, cooldowns and keybinds are unaffected. Pauses in combat, where moving a button is blocked."] = "Lässt die Tasten Deiner Aktionsleisten langsam um das Zentrum der jeweiligen Leiste kreisen, solange der Party Modus aktiv ist. Die Tasten bleiben aufrecht, sodass Klicken, Abklingzeiten und Tastenbelegungen unbeeinträchtigt bleiben. Pausiert im Kampf, wenn das Bewegen von Buttons blockiert ist."
L["Slug outline renders higher quality outlines compared to the base WoW outline mode but may make outline effects appear slightly thicker."] = "Die Slug-Kontur rendert qualitativ hochwertigere Umrisse im Vergleich zum Standard-WoW-Konturmodus, kann Kontureffekte jedoch etwas dicker erscheinen lassen."
L["Slug outline renders higher qualityoutlines compared to the base WoWoutline mode but may make outlineeffects appear slightly thicker."] = "Die Slug-Kontur rendert qualitativ hochwertigere Umrisse im Vergleich zum Standard-WoW-Konturmodus, kann Kontureffekte jedoch etwas dicker erscheinen lassen."
