L["Sorting normally packs your items into the first free slots, at the top of the grid. Turn this on to pack them into the last slots instead, so the empty slots end up at the top. The item order itself does not change. This affects the OneBag, MultiBag and bank views -- category views fill their own grid with no gaps, so there is nothing to move. MultiBag and the bank use Blizzard's own sorting, so while this is on it also flips Blizzard's cleanup direction; turning it back off restores the direction you had."] = "Beim Sortieren werden Deine Gegenstände normalerweise in die ersten freien Plätze oben im Raster einsortiert. Aktiviere diese Option, um sie stattdessen in die letzten Plätze einzusortieren, sodass die freien Plätze oben landen. Die Reihenfolge der Gegenstände selbst ändert sich nicht. Dies betrifft die Ansichten 'Einheitliche Tasche', 'Mehrere Taschen' und 'Bank' – Kategorieansichten füllen ihr eigenes Raster lückenlos, sodass nichts verschoben werden muss. 'Mehrere Taschen' und die Bank nutzen Blizzards eigene Sortierung; bei aktivierter Option wird daher auch Blizzards Aufräumrichtung umgekehrt. Das Deaktivieren stellt die ursprüngliche Richtung wieder her."
