L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "Färbt einen Eintrag ein, der im Moment nichts bewirken würde: Rot, wenn das Ziel außer Reichweite ist; Blau, wenn Ressourcen fehlen; und Grau, wenn das Spiel die Ausführung aus anderen Gründen verweigert. Nur für Zauber und Gegenstände – das Spiel meldet jedes Spielzeug als unbenutzbar, und die Nutzbarkeit eines Makros hängt von dessen Inhalt ab."
L["Tint the cast bar with the Important colour when the enemy casts a spell the game flags as important. Overrides the Interruptible Cast colour; your interrupt being on cooldown still takes priority."] = "Färbt die Zauberleiste in der 'Wichtig' Farbe, wenn der Feind einen als wichtig markierten Zauber wirkt. Überschreibt die Farbe für unterbrechbare Zauber; Ihre eigene Abklingzeit hat dennoch Priorität."
L["Tint the cast bar with the Important colour when the unit casts a spell the game flags as important. Your interrupt being on cooldown still takes priority."] = "Färbt die Zauberleiste mit der Farbe 'Wichtig' ein, wenn die Einheit einen Zauber wirkt, den das Spiel als wichtig markiert. Wenn sich Deine Unterbrechung in Abklingzeit befindet, hat dies weiterhin Vorrang."
L["Tints the pattern with the bar's current color instead of the custom overlay color."] = "Färbt das Muster mit der aktuellen Farbe der Leiste ein statt mit der benutzerdefinierten Überlagerungsfarbe."
L["Tints this block's slot with its own color."] = "Färbt den Platz dieses Blocks mit seiner eigenen Farbe ein."
