L["Use a world marker entry again to pick that marker back up. Off places the marker again, at the new position.\nThis does not change the entry that clears all world markers, or the cycling entry."] = "Verwende einen Weltmarkierungs-Eintrag erneut, um diese Markierung wieder aufzuheben. Wenn deaktiviert, wird die Markierung an der neuen Position erneut platziert.\nDies ändert nicht den Eintrag zum Entfernen aller Weltmarkierungen oder den Durchschalte-Eintrag."
