L["User-created info bars: clock, gold, XP, micro menu and more."] = "Vom Benutzer erstellte Infoleisten: Uhr, Gold, EP, Mikromenü und mehr."
L["Uses a random hearthstone toy variant each cast."] = "Verwendet bei jedem Benutzen eine zufällige Ruhesteinspielzeug Variante."
L["Uses Blizzard's coin textures instead of the letter suffixes."] = "Verwendet Blizzards Münztexturen anstelle der Buchstaben Suffixe."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Verwendet den Eintrag, auf den Du zeigst, während ein Menü mit 'Menü offen halten' geöffnet bleibt. Eine gemeinsame Taste für jedes Menü, die nur belegt ist, während ein Menü aktiv ist – eine Maustaste behält ansonsten ihre normale Funktion."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Verwendet den Eintrag, auf den Du zeigst, während ein Menü mit 'Menü offen halten' geöffnet bleibt. Eine gemeinsame Taste für jedes Menü, die nur belegt ist, während ein Menü aktiv ist – eine Maustaste behält ansonsten ihre normale Funktion.\n\nLinksklick zum Festlegen einer Tastenbelegung, dann drücke eine beliebige Taste oder\nklicke eine Maustaste, um sie zu nutzen.\nEscape bricht ab. Rechtsklick hier hebt die Belegung auf."
L["Uses the Hover Effect color and opacity. Set to None for the flat hover highlight."] = "Nutzt Farbe/Deckkraft des Hover Effekts. Auf 'Keine' setzen für flache Hervorhebung."
