L["Welcome to EllesmereUI"]  = "Willkommen bei EllesmereUI"
L["What's new in EllesmereUI."] = "Was ist neu in EllesmereUI."
L["Wheel Down"] = "Mausrad nach unten"
L["Wheel Up"] = "Mausrad nach oben"
L["When All Missing"] = "Wenn alle fehlen"
L["When All Present"] = "Wenn alle vorhanden sind"
L["When Any Missing"] = "Wenn irgendeiner fehlt"
L["When Any Present"] = "Wenn irgendeiner vorhanden ist"
L["When disabled, EUI relinquishes full control of friendly player nameplates to Blizzard. Use Blizzard's own Nameplate settings (Esc > Options > Nameplates) to control them."] = "Wenn deaktiviert, übergibt EUI die volle Kontrolle über freundliche Namensplaketten an Blizzard. Nutzen Sie Blizzards Einstellungen zur Steuerung."
L["When Dragonriding"] = "Beim Drachenreiten"
L["When enabled, BM and MM specs show Focus as the standard power bar instead of a class resource bar."] = "Wenn aktiviert, zeigen BM- und MM Jäger den Fokus als Standard Energieleiste anstelle der Klassenressourcenleiste."
L["When enabled, debuff icons keep Blizzard's colored border instead of using the custom border."] = "Wenn aktiviert, behalten Schwächungszaubersymbole den farbigen Rahmen von Blizzard anstelle des benutzerdefinierten Rahmens."
L["When enabled, EUI relinquishes full control of friendly player nameplates to Blizzard."] = "Wenn aktiviert, übergibt EUI die volle Kontrolle über freundliche Namensplaketten an Blizzard."
L["When enabled, left-click dragging a window will save its position without needing to hold Shift. Ctrl+drag still does a temporary move."] = "Wenn aktiviert, speichert das Ziehen mit Linksklick die Fensterposition ohne Shift. Strg+Ziehen bewegt es weiterhin nur temporär."
L["When enabled, left-click dragging the bag window will move it without needing to hold Shift."] = "Wenn aktiviert, verschiebt das Ziehen mit Linksklick das Taschenfenster ohne gedrückte Shift Taste."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position. While dragging, buttons snap to nearby buttons and the minimap border; hold Ctrl together with Shift to disable snapping."] = "Wenn aktiviert, kannst Du jede Minimap Schaltfläche (Post, Kalender, Aufspürung, Addon-Buttons) mit Shift+Klick an eine benutzerdefinierte Position ziehen. Beim Ziehen rasten die Buttons an benachbarten Buttons und am Minimap-Rand ein; halte Strg zusammen mit Shift gedrückt, um das Einrasten zu deaktivieren."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position."] = "Wenn aktiviert, können Sie jeden Minimap-Button mit Shift+Linksklick an eine eigene Position ziehen."
L["When enabled, Shift+Click any sidebar icon to drag it to a custom position."] = "Wenn aktiviert, kannst Du jedes Seitenleistensymbol mit Shift+Linksklick an eine eigene Position ziehen."
L["When enabled, the extra buttons (Great Vault, M+ Portals, Friends Online, Group Button) and any ungrouped minimap buttons only show while the mouse is over the minimap. The M+ Portals flyout keeps them shown until it closes."] = "Wenn aktiviert, werden Extra-Buttons an der Minimap nur beim Darüberfahren eingeblendet."
L["When Healing"] = "Beim Heilen"
L["When hovering any action bar set to Mouseover, all Mouseover bars will appear."] = "Wenn Sie über eine auf 'Mouseover' gesetzte Leiste fahren, werden alle Mouseover Leisten eingeblendet."
L["When Not Dragonriding"] = "Nicht beim Drachenreiten"
L["When on, flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Wenn aktiviert, werden Erinnerungen für Fläschchen/Essen/Waffenverzauberung weiterhin (abgedunkelt) angezeigt, selbst wenn Du keinen passenden Gegenstand in den Taschen hast – als Hinweis zum Nachfüllen.\nWenn deaktiviert, werden sie vollständig ausgeblendet, falls Du den Gegenstand nicht bei Dir führst."
L["When Present"] = "Wenn vorhanden"
L["When the class resource bar is not shown, this automatically adds the class resource height to the power bar."] = "Wenn die Klassenressourcenleiste nicht angezeigt wird, fügt dies automatisch deren Höhe zur Energieleiste hinzu."
L["When the current spec has no bars in this group, keeps elements anchored to the group in place and shifts them up or down by one bar height (tune with the cog's Extra Y Offset) to cover its empty slot."] = "Wenn die aktuelle Spezialisierung keine Leisten in dieser Gruppe hat, bleiben die an der Gruppe verankerten Elemente an Ort und Stelle und verschieben sich um eine Leistenhöhe nach oben oder unten (Feineinstellung über das Zahnrad 'Zusätzlicher Y-Versatz'), um den leeren Platz abzudecken."
L["When using custom raid sizes, don't count members in hidden groups toward the raid-size breakpoint. For example, if you hide groups 7 and 8, a full 40-man raid is sized as if it were 24-man instead of jumping to the 30-man frame size. Has no effect unless you have custom raid sizes set up."] = "Zählt Mitglieder in versteckten Gruppen bei benutzerdefinierten Schlachtzugsgrößen nicht zum Schwellenwert für die Schlachtzugsgröße mit. Wenn Du beispielsweise Gruppe 7 und 8 ausblendest, wird ein voller 40-Spieler Schlachtzug so skaliert, als wäre er ein 24-Spieler Schlachtzug, anstatt zur 30-Spieler-Fenstergröße zu springen. Hat keine Wirkung, außer wenn benutzerdefinierte Schlachtzugsgrößen eingerichtet sind."
L["When you are solo, center the player frame on the party frame instead of anchoring it at the top."] = "Zentriert das Spielerfenster auf dem Gruppenfenster, wenn Du alleine bist, anstatt es oben zu verankern."
L["When you join a Group Finder group for a dungeon that has a teleport, shows a small movable popup with the dungeon name and a one-click teleport button. It hides when you enter the dungeon, leave the group, or enter combat."] = "Zeigt beim Beitritt zu einer Gruppe für einen Dungeon mit Teleport ein kleines Popup mit einer One-Click Teleporttaste an."
L["When you press an ability's keybind, show the action button's \"pushed down\" look on its icon on this bar -- even while the ability is on cooldown."] = "Wenn du die Tastenbelegung einer Fähigkeit drückst, wird das Symbol auf dieser Leiste im gedrückten Zustand angezeigt – selbst wenn die Fähigkeit eine Abklingzeit hat."
L["When you press Escape or Space during a cinematic, the confirmation prompt is automatically accepted."] = "Wenn Sie während einer Filmsequenz ESC oder die Leertaste drücken, wird die Bestätigung automatisch akzeptiert."
L["When your bags have none of one combat potion type, its icon swaps to track the next type you own."] = "Wenn Du keine Kampftränke eines Typs mehr in den Taschen hast, wechselt das Symbol zur Verfolgung des nächsten verfügbaren Typs."
L["When your bags have none of one potion type, its icon swaps to track the other type."] = "Wenn sich kein Trank eines Typs in deinen Taschen befindet, wechselt das Symbol, um den anderen Typ zu verfolgen."
L["When your interrupt is on cooldown now but will be ready before the enemy cast finishes, color the part of the cast bar during which your interrupt will be available. The color clears the instant your interrupt comes off cooldown."] = "Wenn Deine Unterbrechung auf Abklingzeit ist, aber vor Ende des feindlichen Zaubers bereit wird, färbt dies den entsprechenden Teil der Zauberleiste ein."
L["When your spec has no class resource, automatically adds the class resource height to the power bar. Automatically disabled when Power Bar height is matched to another element."] = "Wenn Deine Spezialisierung keine Klassenressource hat, wird deren Höhe automatisch zur Energieleiste hinzugefügt."
L["Where the block's content sits inside its slot."] = "Wo sich der Inhalt des Blocks innerhalb seines Platzes befindet."
L["Where the icon strip sits inside its slot."] = "Wo sich die Symbolleiste innerhalb ihres Platzes befindet."
L["Where to Show"] = "Wo anzeigen"
L["Which audio channel the block's volume bar adjusts."] = "Welchen Audiokanal die Lautstärkeleiste dieses Blocks anpasst."
L["Which direction new icons extend from the frame's edge."] = "In welche Richtung sich neue Symbole vom Rand des Frames aus ausdehnen."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Dispellable shows only buffs that can be dispelled, purged or soothed. With a Dispel Glow style set, every dispellable buff shown glows."] = "Bestimmt, welche gegnerischen Stärkungszauber auf Namensplaketten angezeigt werden. 'Wichtig' zeigt die von Blizzard für Namensplaketten markierten Zauber sowie alles Bannbare; 'Bannbar' zeigt nur Zauber, die gebannt, gereinigt oder besänftigt werden können. Mit einem eingestellten Bann Leuchten leuchtet jeder angezeigte bannbare Stärkungszauber."
L["Which hearthstone the left click uses. Random Hearthstone picks a random owned variant each cast. Right click always rolls a random one."] = "Welcher Ruhestein beim Linksklick verwendet wird. 'Zufälliger Ruhestein' wählt bei jedem Wirken eine zufällige besessene Variante aus. Rechtsklick wählt immer einen zufälligen."
L["Which latency to show: home, world, or both side by side."] = "Welche Latenz angezeigt werden soll: Standort, Welt oder beide nebeneinander."
L["Which micro menu buttons this block shows."] = "Welche Tasten des Mikromenüs dieser Block anzeigt."
L["Which minimap corner the Blizzard element row (tracking, calendar, mail, crafting) builds out from and the direction it grows."] = "Aus welcher Ecke der Minimap die Leiste der Blizzard Elemente (Aufspüren, Kalender, Post, Handwerk) hervorgeht und in welche Richtung sie wächst."
L["Which minimap corner the button row builds out from and the direction it grows."] = "Aus welcher Ecke der Minimap die Tastenleiste hervorgeht und in welche Richtung sie wächst."
L["Which sections the gold tooltip shows."] = "Welche Abschnitte der Gold Tooltip anzeigt."
L["Which view bags (and the bank) open to by default. The bank has no MultiBag view, so MultiBag opens the bank to OneBank."] = "Bestimmt, mit welcher Ansicht sich Taschen (und die Bank) standardmäßig öffnen. Die Bank besitzt keine Mehrfachtaschen Ansicht, daher öffnet Mehrfachtasche die Bank in der Einzeltaschen Ansicht."
L["Which way new bars stack as more enemies start casting."] = "In welche Richtung neue Leisten stapeln, wenn mehr Feinde anfangen zu zaubern."
L["Which way the rows stack as healers are added."] = "In welche Richtung die Reihen stapeln, wenn Heiler hinzugefügt werden."
L["while at an Item Upgrade NPC."] = "während bei einem Gegenstandsaufwertungs NPC."
L["While dragging a spell or item, this bar appears so you can drop onto it."] = "Beim Ziehen eines Zaubers oder Gegenstands erscheint diese Leiste, damit Du ihn darauf ablegen kannst."
L["While the spellbook or macro panel is open, this bar appears so you can drag abilities onto it."] = "Während das Zauberbuch oder das Makrofenster geöffnet ist, erscheint diese Leiste, damit Du Fähigkeiten darauf ziehen kannst."
L["Whirlwind Stacks"] = "Wirbelwindstapel"
L["Whisper BNet"] = "BNet Flüstern"
L["Whisper Sound"] = "Flüsterton"
L["Whisper"] = "Flüstern"
L["Whistle"] = "Pfeifen"
L["White Ticks"] = "Weiße Markierungen"
L["Whitelist"] = "Whitelist"
L["Wide Stripes"] = "Breite Streifen"
L["Widens or narrows the boss frames relative to the raid frame size."] = "Verbreitert oder verschmälert die Bossfenster im Verhältnis zur Schlachtzugsfenster Größe."
L["Widens or narrows the extra frames relative to the raid frame size."] = "Verbreitert oder verschmälert die Zusatzfenster im Verhältnis zur Schlachtzugsfenster Größe."
L["Widens the clickable hitbox of enemy nameplates. 100% = matches bar width. Increase to make nameplates easier to click."] = "Verbreitert die anklickbare Hitbox feindlicher Namensplaketten. Erhöhen, um sie leichter anklickbar zu machen."
L["Widget bar reskin requires a UI reload to apply."] = "Das Anpassen der Widget Leisten erfordert ein Neuladen des UI."
L["Width %"] = "Breite %"
L["Width matched to Cast Bar. Unmatch in Unlock Mode to edit."] = "Breite an Zauberleiste angepasst. Im Freigabemodus Entkoppeln zum Bearbeiten."
L["Width matched to Class Resource. Unmatch in Unlock Mode to edit."] = "Breite an Klassenressource angepasst. Im Freigabemodus Entkoppeln zum Bearbeiten."
L["Width matched to GCD Bar. Unmatch in Unlock Mode to edit."] = "Breite an GCD-Leiste angepasst. Im Freigabemodus Entkoppeln zum Bearbeiten."
L["Width matched to Health Bar. Unmatch in Unlock Mode to edit."] = "Breite an Gesundheitsleiste angepasst. Im Freigabemodus Entkoppeln zum Bearbeiten."
L["Width matched to Player Frame. Unmatch in Unlock Mode to edit."] = "Breite an Spielerfenster angepasst. Im Freigabemodus Entkoppeln zum Bearbeiten."
L["Width matched to Power Bar. Unmatch in Unlock Mode to edit."] = "Breite an Ressourcenleiste angepasst. Im Freigabemodus Entkoppeln zum Bearbeiten."
L["Width"] = "Breite"
L["Wild Growth"] = "Wildwuchs"
L["Wilhelm"] = "Wilhelmsruf"
L["Windfury Weapon"] = "Waffe des Windzorns"
L["Window & Tooltip Skins"] = "Fenster- & Tooltip Skins"
L["Window Scale"] = "Fensterskalierung"
L["Window skins are currently disabled for this profile."] = "Fenster Skins sind für dieses Profil derzeit deaktiviert."
L["Window skins are now disabled for this profile. A UI reload is required to restore the stock Blizzard windows."] = "Fenster Skins sind für dieses Profil jetzt deaktiviert. Ein Neuladen des UI ist erforderlich, um Blizzards Standardfenster wiederherzustellen."
L["Window skins are now enabled for this profile. A UI reload is required to apply them."] = "Fenster Skins sind für dieses Profil jetzt aktiviert. Ein Neuladen des UI ist erforderlich, um sie anzuwenden."
