L["Addon List"] = "Addon-Liste"
L["Adds Bonus Roll and Group Loot movers to Unlock Mode."] = "Fügt dem Entsperrmodus Verschiebeobjekte für Bonuswurf und Gruppenbeute hinzu."
L["Adds a Targeting line showing who the hovered player or NPC is targeting, in green when it's you."] = "Fügt eine Ziel-Zeile hinzu, die anzeigt, wen der Spieler oder NSC unter dem Mauszeiger anvisiert – in Grün, wenn du es selbst bist."
L["Adds a compact Raid Tools window -- target/world markers, ready check, role check and pull timer in one resizable row. It runs alongside whichever Show as layout is picked above (or with Raid Tools fully off), moves and resizes independently through Unlock Mode, and only appears while you're actually in a raid group."] = "Fügt ein kompaktes Schlachtzugswerkzeuge-Fenster hinzu -- Ziel-/Weltmarkierungen, Bereitschaftscheck, Rollenabfrage und Pull-Timer in einer skalierbaren Zeile. Es läuft parallel zu dem oben gewählten Anzeigen-als-Layout (oder auch bei vollständig deaktivierten Schlachtzugswerkzeugen), lässt sich über den Entsperrmodus unabhängig verschieben und skalieren und erscheint nur, während du dich tatsächlich in einer Schlachtzugsgruppe befindest."
L["Adds a small filled dot at the center of the cursor circle. Uses the same color and opacity as the circle."] = "Fügt einen kleinen ausgefüllten Punkt in der Mitte des Cursorkreises hinzu. Verwendet dieselbe Farbe und Deckkraft wie der Kreis."
L["Adds the mount a player is riding to their tooltip, with a green check if you own it or a red X if you don't."] = "Fügt dem Tooltip eines Spielers das Reittier hinzu, auf dem er gerade reitet, mit einem grünen Haken, wenn du es besitzt, oder einem roten X, wenn nicht."
L["Adds three optional world-marker keybinds that remain usable in combat. Place drops the first free marker at the cursor in Star to Skull order; Undo removes the last marker placed through Quick Fire; Clear removes all world markers. Every binding starts empty. Marker changes made elsewhere during combat are picked up afterward."] = "Fügt drei optionale Tastenbelegungen für Weltmarkierungen hinzu, die auch im Kampf nutzbar bleiben. „Setzen“ platziert die erste freie Markierung an der Cursorposition in der Reihenfolge Stern bis Totenkopf; „Rückgängig“ entfernt die zuletzt per Schnellfeuer gesetzte Markierung; „Löschen“ entfernt alle Weltmarkierungen. Jede Tastenbelegung ist anfangs leer. Markierungsänderungen, die im Kampf anderweitig vorgenommen wurden, werden danach übernommen."
L["AdiBags"] = true
L["Adjust Volume"] = "Lautstärke anpassen"
L["After anchoring, drag to an edge and choose a grow direction to maintain its corner spot as bars change size."] = "Ziehe es nach der Verankerung an eine Kante und wähle eine Wachstumsrichtung, damit seine Eckposition erhalten bleibt, wenn sich die Größe der Leisten ändert."
L["Agility %d (%d-%d)"] = "Beweglichkeit %d (%d-%d)"
L["Aimed Shot"] = "Zielschuss"
L["Alerts, trackers, battle res and popup text"] = "Warnungen, Tracker, Kampfwiederbelebung und Popup-Text"
L["All Classes"] = "Alle Klassen"
L["All Other Specs"] = "Alle anderen Spezialisierungen"
L["All entries in the Threshold Settings spec dropdown are now clickable."] = "Alle Einträge im Spezialisierungs-Dropdown der Schwellenwert-Einstellungen sind jetzt anklickbar."
L["Allowed Demons picks which demons count as correct for any Warlock spec, and the Missing Pet reminder now summons on click"] = "„Erlaubte Dämonen“ legt fest, welche Dämonen für jede Hexenmeister-Spezialisierung als korrekt gelten, und die Erinnerung „Fehlendes Begleitwesen“ beschwört jetzt per Klick"
