L["Already used by another card for this spec"] = "Bereits von einer anderen Karte für diese Spezialisierung verwendet"
L["Also use the split dialog with Auto Split in OneBag, MultiBag, the reagent bag, the bank and the guild bank, replacing Blizzard's split popup there. All Items and category views always use it."] = "Verwendet den Teilen-Dialog mit Auto-Teilen auch in OneBag, MultiBag, der Reagenzientasche, der Bank und der Gildenbank und ersetzt dort Blizzards Teilen-Popup. Die Ansichten „Alle Gegenstände“ und Kategorien verwenden ihn immer."
L["Altar of Fangs"] = "Altar der Fänge" -- TODO: confirmar termo oficial
L["Always Show Split Times"] = "Split-Zeiten immer anzeigen"
L["Always Show While Skyriding /\nIn Vehicle"] = "Immer anzeigen beim Himmelsreiten /\nIm Fahrzeug"
L["Always Visible"] = "Immer sichtbar"
L["Always color the item level by item rarity instead of its upgrade track."] = "Färbt die Gegenstandsstufe immer nach der Seltenheit des Gegenstands statt nach seiner Aufwertungsstufe."
L["Always keeps it fully visible. Mouseover fades it out until the cursor is over it."] = "Hält es immer vollständig sichtbar. Mouseover blendet es aus, bis sich der Cursor darüber befindet."
L["Always keeps the shown windows and the button that opens them fully visible. Mouseover fades them out until you move your cursor over them."] = "Hält die angezeigten Fenster und die Schaltfläche, die sie öffnet, immer vollständig sichtbar. Mouseover blendet sie aus, bis du den Cursor darüberbewegst."
L["Always on for Whirlwind and Sweeping Strikes charges: range coloring at/above the threshold is the only way these bars can display thresholds."] = "Bei Aufladungen von Wirbelwind und Rundumschlag immer aktiv: Die Reichweitenfärbung am bzw. über dem Schwellenwert ist die einzige Möglichkeit, wie diese Leisten Schwellenwerte anzeigen können."
L["Always show Blizzard's bright rotating edge on cooldowns in this bar. Hide Recharge Edge still overrides this for individual charge spells."] = "Zeigt immer Blizzards helle, rotierende Kante bei Abklingzeiten in dieser Leiste. „Aufladekante ausblenden“ überschreibt dies weiterhin für einzelne Aufladezauber."
L["Always shows the chat tabs. Mouseover hides them until you move the cursor over the tab bar."] = "Zeigt die Chat-Reiter immer an. Mouseover blendet sie aus, bis du den Cursor über die Reiterleiste bewegst."
L["Always use K/M/B instead of localized units."] = "Immer K/M/B anstelle lokalisierter Einheiten verwenden."
L["Ambience"] = "Umgebungsgeräusche"
L["Anchor icons and text as if no power bar existed, so frames with and without one line up identically."] = "Verankert Symbole und Text so, als gäbe es keine Ressourcenleiste, damit Fenster mit und ohne diese identisch ausgerichtet sind."
L["Anchor the text inside the bar. The X/Y offsets move it from there."] = "Verankert den Text innerhalb der Leiste. Die X-/Y-Versätze verschieben ihn von dort aus."
L["Another override group already provides the custom unlock mode for your current spec."] = "Eine andere Überschreibungsgruppe stellt bereits den benutzerdefinierten Entsperrmodus für deine aktuelle Spezialisierung bereit."
L["Any LibDataBroker plugin registered right now. One block per plugin -- add the block again for a second one."] = "Jedes aktuell registrierte LibDataBroker-Plugin. Ein Block pro Plugin -- füge den Block erneut hinzu, um einen zweiten zu erhalten."
L["Any debuff with a dispel type (Magic, Curse, Disease, Poison, Bleed), even if you cannot remove it."] = "Jeder Debuff mit einem Banntyp (Magie, Fluch, Krankheit, Gift, Bluten), selbst wenn du ihn nicht entfernen kannst."
