L["Choose the spec to copy trinkets, pots, racials & buff presets from"] = "Wählt die Spezialisierung, von der Schmuckstücke, Tränke, Rasseneffekte & Buff-Vorlagen kopiert werden sollen"
L["Choose which addons to include in your exported profile. Check everything for a full profile export."] = "Wählen Sie, welche Addons in Ihr exportiertes Profil aufgenommen werden. Aktivieren Sie alles für einen vollständigen Profilexport."
L["Choose which channels get a bubble.\n\nSay, Yell, NPCs and Emotes share one Blizzard switch. It is turned on while at least one of the four is ticked, and put back the way you had it once you clear the last one. Party and Raid have switches of their own and start out matching what you already had, so no group bubbles turn up in a chat that had none.\n\nGuild is not offered: Blizzard draws no bubble for guild chat, and there is nothing for us to restyle."] = "Wählen Sie, welche Kanäle eine Sprechblase erhalten.\n\nSagen, Rufen, NSCs und Emotes teilen sich einen gemeinsamen Blizzard-Schalter. Er ist aktiv, solange mindestens einer der vier angehakt ist, und wird wieder in den vorherigen Zustand versetzt, sobald der letzte deaktiviert wird. Gruppe und Schlachtzug haben eigene Schalter und starten mit dem Zustand, den Sie bereits hatten, sodass in einem Chat ohne Gruppen-Sprechblasen auch keine erscheinen.\n\nGilde wird nicht angeboten: Blizzard zeichnet keine Sprechblase für den Gildenchat, und es gibt nichts für uns neu zu gestalten."
