L["Clickable links and player names on lines with shortened channel names now respond exactly where they appear, and the wheel scrolls into restored history right after a reload."] = "Anklickbare Links und Spielernamen in Zeilen mit verkürzten Kanalnamen reagieren jetzt genau dort, wo sie erscheinen, und das Mausrad scrollt direkt nach einem Neuladen in den wiederhergestellten Verlauf."
