L["Close to Aggro"] = "Kurz vor Aggro"
L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Schließt ein geöffnetes Menü, ohne etwas zu verwenden. Escape tut dies ebenfalls immer. Eine Taste, die sich jedes Menü teilt und nur beansprucht wird, während ein Menü geöffnet ist -- eine Maustaste behält den Rest der Zeit ihre normale Funktion."
L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Schließt ein geöffnetes Menü, ohne etwas zu verwenden. Escape tut dies ebenfalls immer. Eine Taste, die sich jedes Menü teilt und nur beansprucht wird, während ein Menü geöffnet ist -- eine Maustaste behält den Rest der Zeit ihre normale Funktion.\n\nLinksklick, um eine Tastenbelegung festzulegen, dann eine beliebige Taste drücken oder\neine beliebige Maustaste klicken, um sie zu verwenden.\nEscape bricht ab. Rechtsklick hier, um die Belegung zu entfernen."
L["Cobra Shot"] = "Kobraschuss"
L["Collapse subgroups that have no members so the remaining groups close ranks. For example, if only groups 1, 2, 3 and 6 have players, they show with no gaps instead of leaving empty space where groups 4 and 5 would be. Real raid frames only."] = "Klappt Untergruppen ohne Mitglieder zusammen, sodass die verbleibenden Gruppen lückenlos aufrücken. Wenn beispielsweise nur die Gruppen 1, 2, 3 und 6 Spieler haben, werden sie ohne Lücken angezeigt, anstatt Leerraum für die Gruppen 4 und 5 zu lassen. Nur bei echten Schlachtzugsfenstern."
L["Collapses the windows back to the icon on their own after they've been open (and the cursor hasn't been over them) for the delay below -- the same result as clicking the close button, just on a timer. Moving the cursor over the windows pauses the timer and it starts over once you look away."] = "Klappt die Fenster nach der unten festgelegten Verzögerung von selbst wieder zum Symbol zusammen (sofern sich der Cursor nicht darüber befand) -- dasselbe Ergebnis wie ein Klick auf die Schließen-Schaltfläche, nur zeitgesteuert. Bewegst du den Cursor über die Fenster, pausiert der Timer und beginnt von Neuem, sobald du wegschaust."
L["Colon (5:32)"] = "Doppelpunkt (5:32)"

