L["Color the bar by ranges instead of a single threshold.\nUp to (<=) / From (>=)\nAny remaning values outside the bands will use fill color.\n|cff888888Bars can use % or actual value; pip resources use counts.|r"] = "Färbt die Leiste nach Bereichen statt nach einem einzelnen Schwellenwert.\nBis zu (<=) / Ab (>=)\nAlle verbleibenden Werte außerhalb der Bänder verwenden die Füllfarbe.\n|cff888888Leisten können % oder den tatsächlichen Wert verwenden; Punkt-Ressourcen verwenden Zählwerte.|r"
L["Color the bar differently at several stack counts. The highest count you have reached wins."] = "Färbt die Leiste bei mehreren Stapelzahlen unterschiedlich. Die höchste erreichte Zahl gewinnt."
L["Colored Percentages"] = "Farbige Prozentwerte"
