L["Configurable text color, size, bar height and text position for the queue accept countdown, via a swatch and cog beside Show Queue Timer"] = "Konfigurierbare Textfarbe, -größe, Leistenhöhe und Textposition für den Warteschlangen-Annahme-Countdown, über eine Farbfläche und ein Zahnrad neben „Warteschlangen-Timer anzeigen“"
