L["Controls the frame layering (strata) this bar renders on. Raise it if the bar is being covered by another window; lower it if it should render behind other UI."] = "Steuert die Fensterebene (Strata), auf der diese Leiste dargestellt wird. Erhöhe sie, wenn die Leiste von einem anderen Fenster verdeckt wird; verringere sie, wenn sie hinter anderen UI-Elementen erscheinen soll."
L["Controls the highlight shown over a nameplate when you mouse over it. Set to 0 to disable."] = "Steuert die Hervorhebung, die über einem Namensschild angezeigt wird, wenn du mit der Maus darüberfährst. Auf 0 setzen, um sie zu deaktivieren."
L["Controls where status icons are displayed. Use the individual settings to choose which icons are shown: Ready Check, Resurrection, Other Phase, or Other Party."] = "Steuert, wo Statussymbole angezeigt werden. Verwende die einzelnen Einstellungen, um festzulegen, welche Symbole angezeigt werden: Bereitschaftscheck, Wiederbelebung, Andere Phase oder Andere Gruppe."
L["Controls where the incoming-summon icon is displayed, independent of the Status Icon slot above."] = "Steuert, wo das Symbol für eine eingehende Beschwörung angezeigt wird, unabhängig vom obigen Statussymbol-Platz."
L["Controls whether the Dead status text is displayed and where, independent of the Offline/AFK Status Text above."] = "Steuert, ob und wo der Status-Text „Tot“ angezeigt wird, unabhängig vom obigen Offline-/AFK-Status-Text."
L["Controls whether the Offline/AFK status text is displayed and where. Dead status text has its own independent settings below."] = "Steuert, ob und wo der Offline-/AFK-Status-Text angezeigt wird. Der Status-Text „Tot“ hat unten eigene, unabhängige Einstellungen."
