L["Determine the raid-size breakpoint from the number of active subgroups (each active group counts as 5) instead of total headcount. For example, spreading 8 players one per group across all 8 raid groups resolves to a 40-man breakpoint instead of an 8-man one. Off by default: the breakpoint uses raw headcount."] = "Ermittelt den Schlachtzugsgrößen-Schwellenwert anhand der Anzahl aktiver Untergruppen (jede aktive Gruppe zählt als 5) statt der Gesamtkopfzahl. Verteilt man beispielsweise 8 Spieler auf jeweils einen pro Gruppe über alle 8 Schlachtzugsgruppen, ergibt das einen 40er-Schwellenwert statt eines 8er-Schwellenwerts. Standardmäßig aus: Der Schwellenwert verwendet die reine Kopfzahl."
