L["Dream Flight\n(Cursor)"] = "Traumflug\n(Cursor)"
L["Drop the individual Tab 1 / Tab 2 / Warbank Tab entries once the category list is doing the navigating. The consolidated views stay. Note that right-clicking a tab entry is the only way to rename a tab or change its deposit filters, so leave this off if you still need that."] = "Entfernt die einzelnen Einträge „Fach 1“ / „Fach 2“ / „Kriegshorten-Fach“, sobald die Kategorieliste die Navigation übernimmt. Die zusammengefassten Ansichten bleiben erhalten. Beachte, dass ein Rechtsklick auf einen Fach-Eintrag die einzige Möglichkeit ist, ein Fach umzubenennen oder seine Einlagerungsfilter zu ändern -- lasse dies daher deaktiviert, falls du das noch brauchst." -- TODO: confirmar termo oficial (Warbank)
L["Drops columns nothing in this group can satisfy instead of greying them: no mage means no Intellect column, and a Mythic+ key means no Vantus. Turn off to keep every column in place whatever the group."] = "Entfernt Spalten, die niemand in dieser Gruppe erfüllen kann, statt sie nur auszugrauen: kein Magier bedeutet keine Intelligenz-Spalte, und ein Mythisch-Plus-Schlüsselstein bedeutet keine Vantus-Rune. Deaktivieren, um jede Spalte unabhängig von der Gruppe beizubehalten."
L["Drops crests you own none of, keeping the block short early in a season. They stay listed in the tooltip."] = "Entfernt Wappen, von denen du keine besitzt, damit der Block früh in der Saison kurz bleibt. Sie bleiben im Tooltip gelistet."
L["Druid travel, aquatic and flight forms count as mounted."] = "Druiden-Reise-, Wasser- und Flugformen zählen als beritten."
L["Due to Blizzard API restrictions, Blizzard's native %s can't be hidden in combat and will show the whole time you are in combat. Recommended: match the %s frame's source -- both Blizzard Default, or both EllesmereUI."] = "Aufgrund von Blizzard-API-Einschränkungen kann Blizzards natives %s im Kampf nicht ausgeblendet werden und wird während des gesamten Kampfes angezeigt. Empfohlen: Die Quelle des %s-Fensters angleichen -- entweder beide auf Blizzard-Standard oder beide auf EllesmereUI."
L["Due to Blizzard API restrictions, Blizzard's native focus-target can't be hidden in combat and will show the whole time you are in combat. Recommended: match the Focus frame's source -- both Blizzard Default, or both EllesmereUI."] = "Aufgrund von Blizzard-API-Einschränkungen kann Blizzards natives Fokus-Ziel im Kampf nicht ausgeblendet werden und wird während des gesamten Kampfes angezeigt. Empfohlen: Die Quelle des Fokus-Fensters angleichen -- entweder beide auf Blizzard-Standard oder beide auf EllesmereUI."
L["Due to Blizzard API restrictions, Blizzard's native target-of-target can't be hidden in combat and will show the whole time you are in combat. Recommended: match the Target frame's source -- both Blizzard Default, or both EllesmereUI."] = "Aufgrund von Blizzard-API-Einschränkungen kann Blizzards natives Ziel-des-Ziels im Kampf nicht ausgeblendet werden und wird während des gesamten Kampfes angezeigt. Empfohlen: Die Quelle des Ziel-Fensters angleichen -- entweder beide auf Blizzard-Standard oder beide auf EllesmereUI."
