L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n1. Disable EllesmereUI Cooldown Manager (button below).\n2. Open Edit Mode from the Game Menu.\n3. Select each Cooldown Manager viewer and set Visibility to Always.\n4. On Tracked Buffs and Tracked Bars, tick Hide When Inactive.\n5. Save the layout and leave Edit Mode.\n6. Re-enable EllesmereUI Cooldown Manager."] = "EllesmereUI konnte diese Änderung nicht in deinem Bearbeitungsmodus-Layout speichern, daher muss sie von Hand vorgenommen werden. Der Abklingzeit-Manager muss dabei deaktiviert sein, da er Blizzards Abklingzeit-Anzeigen ausblendet und eine ausgeblendete Anzeige im Bearbeitungsmodus nicht ausgewählt werden kann.\n\n1. EllesmereUI-Abklingzeit-Manager deaktivieren (Schaltfläche unten).\n2. Bearbeitungsmodus über das Spielmenü öffnen.\n3. Jede Abklingzeit-Manager-Anzeige auswählen und Sichtbarkeit auf „Immer“ setzen.\n4. Bei „Verfolgte Buffs“ und „Verfolgte Leisten“ „Bei Inaktivität ausblenden“ ankreuzen.\n5. Layout speichern und Bearbeitungsmodus verlassen.\n6. EllesmereUI-Abklingzeit-Manager wieder aktivieren."
L["EllesmereUI restyles Blizzard's chat bubbles and turns on the switches it needs. Party and Raid keep your current setting, and everything is put back when you turn this off."] = "EllesmereUI gestaltet Blizzards Chat-Sprechblasen neu und aktiviert die dafür benötigten Schalter. Gruppe und Schlachtzug behalten deine aktuelle Einstellung, und alles wird zurückgesetzt, wenn du dies deaktivierst."
L["ElvUI"] = true
L["Emotes"] = true
L["Empty Slots"] = "Leere Plätze"

