L["Fades just the cast bar when the boss is out of range of your spells. Set to 100% to disable the fade."] = "Blendet nur die Zauberleiste aus, wenn der Boss außerhalb der Reichweite deiner Zauber ist. Auf 100% setzen, um das Ausblenden zu deaktivieren."
L["Fades just the cast bar when the unit is out of range of your spells. Set to 100% to disable the fade."] = "Blendet nur die Zauberleiste aus, wenn die Einheit außerhalb der Reichweite deiner Zauber ist. Auf 100% setzen, um das Ausblenden zu deaktivieren."
L["Fades the entire frame (portrait, health and power bars, text) while out of combat."] = "Blendet das gesamte Fenster aus (Porträt, Gesundheits- und Ressourcenleiste, Text), während du dich nicht im Kampf befindest."
