L["Hide and show every damage meter window at once. The state is not saved; a reload restores the configured visibility.\n\nThe bound key is taken over while it is set. Use the cog to include the combat timer and Spell History.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Blendet alle Schadensmesser-Fenster gleichzeitig aus und wieder ein. Der Zustand wird nicht gespeichert; ein Neuladen stellt die konfigurierte Sichtbarkeit wieder her.\n\nDie belegte Taste wird beansprucht, solange sie gesetzt ist. Verwende das Zahnrad, um den Kampf-Timer und den Zauberverlauf einzuschließen.\n\nLinksklick, um eine Tastenbelegung festzulegen.\nRechtsklick, um die Belegung zu entfernen."
L["Hide every Cooldown Manager glow out of combat and bring them all back the moment you enter combat."] = "Blendet jedes Leuchten des Abklingzeit-Managers außerhalb des Kampfes aus und bringt sie alle zurück, sobald du in den Kampf eintrittst."
L["Hide every Cooldown Manager glow while you are out of combat: proc glows, active state, max stacks, buff and pandemic glows, cooldown ready glows and bar glows.\n\nThey come back the moment you enter combat, including a glow that started before the pull.\n\nApplies to every CDM bar and to the Tracking Bars at once. Glows from other EllesmereUI modules are not affected.\n\nThe Bar Glows page keeps its own per-mapping Only In Combat toggle; this one applies on top of it."] = "Blendet jedes Leuchten des Abklingzeit-Managers aus, während du dich nicht im Kampf befindest: Proc-Leuchten, aktiver Zustand, maximale Stapel, Buff- und Pandemie-Leuchten, Abklingzeit-bereit-Leuchten und Leisten-Leuchten.\n\nSie kehren zurück, sobald du in den Kampf eintrittst, einschließlich eines Leuchtens, das bereits vor dem Pull begonnen hat.\n\nGilt gleichzeitig für jede CDM-Leiste und für die Trackingleisten. Leuchten anderer EllesmereUI-Module sind nicht betroffen.\n\nDie Seite „Leisten-Leuchten“ behält ihren eigenen Schalter „Nur im Kampf“ pro Zuordnung; dieser wirkt zusätzlich dazu."
L["Hide role icons while you are in combat."] = "Blendet Rollensymbole aus, während du dich im Kampf befindest."
L["Hide the 1-pixel border around the cast bar spell icon."] = "Blendet den 1-Pixel-Rahmen um das Zaubersymbol der Zauberleiste aus."
L["Hide the 1-pixel outline around the bar."] = "Blendet die 1-Pixel-Kontur um die Leiste aus."
L["Hide the tooltip when hovering a buff/HoT icon on a raid or party frame."] = "Blendet den Tooltip beim Überfahren eines Buff-/HoT-Symbols auf einem Schlachtzugs- oder Gruppenfenster aus."
L["Hide when Dragonriding"] = "Beim Drachenreiten ausblenden"
L["Hide while this condition is true"] = "Ausblenden, solange diese Bedingung zutrifft"
L["Hides the Top Bar Event Text mover in Unlock Mode while keeping its saved position applied."] = "Blendet das Verschiebeobjekt für den Ereignistext der oberen Leiste im Entsperrmodus aus, während dessen gespeicherte Position weiterhin angewendet bleibt."
L["Hides the loot window movers in Unlock Mode while keeping their saved positions applied."] = "Blendet die Verschiebeobjekte des Beutefensters im Entsperrmodus aus, während deren gespeicherte Positionen weiterhin angewendet bleiben."
L["Hides this element while you are on a skyriding (glide-capable) mount, where Blizzard shows its vigor HUD."] = "Blendet dieses Element aus, während du auf einem himmelsreitfähigen (gleitfähigen) Reittier bist, wo Blizzard sein Elan-HUD anzeigt."
L["Highest First"] = "Höchste zuerst"
L["Highest group size that uses this layout."] = "Größte Gruppengröße, die dieses Layout verwendet."
L["Highlight Border"] = "Hervorhebungsrahmen"
L["Hold Capped Artisan Payouts"] = "Gedeckelte Handwerksmeister-Auszahlungen zurückhalten" -- TODO: confirmar termo oficial
L["Hold a keybind to open a palette of actions; point or scroll to choose, release to fire."] = "Halte eine Tastenbelegung gedrückt, um eine Aktionspalette zu öffnen; zeige oder scrolle zur Auswahl, lasse los, um sie auszuführen."
L["Holds the block at this width and clips longer text, so a plugin whose text keeps changing length never shifts the blocks beside it. Zero sizes the block to whatever the plugin currently says."] = "Hält den Block auf dieser Breite und schneidet längeren Text ab, sodass ein Plugin mit wechselnder Textlänge die danebenliegenden Blöcke nie verschiebt. Null passt den Block an das an, was das Plugin aktuell anzeigt."
