-- == Batch 2026-09-16 (missing_deDE.txt lines 1031-1290) ==
L["Hovering names in the Guild & Communities roster no longer errors, and member tooltips keep their race and class lines."] = "Das Überfahren von Namen in der Gilden- & Communities-Liste verursacht keinen Fehler mehr, und Mitglieder-Tooltips behalten ihre Rassen- und Klassenzeilen."
L["How Blizzard's next-spell suggestion is drawn on the button. Button Overlay replaces the blue ring with a flat tint, leaving the button edge free for the proc glow."] = "Wie Blizzards Vorschlag für den nächsten Zauber auf der Schaltfläche dargestellt wird. „Button-Overlay“ ersetzt den blauen Ring durch eine flache Einfärbung und lässt den Schaltflächenrand für das Proc-Leuchten frei."
L["How extra columns grow when the second column appears or disappears. Grow Right keeps the left column in place, Grow Left keeps the right column in place, Grow Centered keeps the bar centered."] = "Wie zusätzliche Spalten wachsen, wenn die zweite Spalte erscheint oder verschwindet. „Nach rechts wachsen“ hält die linke Spalte an ihrem Platz, „Nach links wachsen“ hält die rechte Spalte an ihrem Platz, „Zentriert wachsen“ hält die Leiste zentriert."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span. A nest reaches over the plain entries it passes, and they only give up their angles while it is open."] = "Wie weit entlang des Bogens ein Nest seine Einträge verteilen darf. „Eingegrenzt“ hält es von den benachbarten Nestern auf beiden Seiten fern, sodass zwei davon nie übereinander gezeichnet werden. „Überlaufend“ erlaubt die volle Nutzung von „Maximale Nest-Spanne“. Ein Nest erstreckt sich über die einfachen Einträge, die es passiert, und diese geben ihre Winkel nur frei, solange es geöffnet ist."
L["How long the windows stay open, cursor off them, before Auto-Minimize collapses them."] = "Wie lange die Fenster geöffnet bleiben, ohne dass sich der Cursor darüber befindet, bevor „Automatisch minimieren“ sie einklappt."
L["How many decimal places the number carries."] = "Wie viele Dezimalstellen die Zahl trägt."
L["How many icons to show on the bottom row. The rest go on the top row."] = "Wie viele Symbole in der unteren Zeile angezeigt werden. Der Rest kommt in die obere Zeile."
L["How many icons to show on the top row. The rest go on the bottom row."] = "Wie viele Symbole in der oberen Zeile angezeigt werden. Der Rest kommt in die untere Zeile."
L["How many pixels the custom effect extends beyond the icon."] = "Wie viele Pixel der benutzerdefinierte Effekt über das Symbol hinausragt."
