L["Keeps Artisan's Consortium Payouts closed while Shard of Dundun is at its maximum, then resumes automatic opening after you spend shards."] = "Hält die Auszahlungen des Handwerksmeister-Konsortiums geschlossen, solange der Splitter von Dundun sein Maximum erreicht hat, und öffnet danach automatisch wieder, sobald du Splitter ausgibst." -- TODO: confirmar termo oficial (Artisan's Consortium / Shard of Dundun)
L["Keeps a saved signup note you can copy into the Sign Up dialog with the Copy button."] = "Bewahrt eine gespeicherte Anmeldenotiz, die du mit der Schaltfläche „Kopieren“ in den Anmeldedialog einfügen kannst."
