L["Liquid Luster is available as a Custom Buff Bar potion preset alongside Light's Potential and Potion of Recklessness."] = "„Liquid Luster“ ist als Trank-Vorlage für die benutzerdefinierte Buff-Leiste verfügbar, neben „Light's Potential“ und „Trank der Tollkühnheit“." -- TODO: confirmar termo oficial (Liquid Luster / Light's Potential)
L["List item categories in the bank sidebar the way the bags sidebar does -- groups such as The Armory with Weapons and Armor under them. Selecting one filters the grid to that category. Categories that split further list their parts as a third level while selected: Professions by profession, Armor by equipment slot, Trade Goods by material. Spans your character bank and warband together, so a category shows everything you own."] = "Listet Gegenstandskategorien in der Bank-Seitenleiste genauso auf wie in der Taschen-Seitenleiste -- Gruppen wie „Die Rüstkammer“ mit Waffen und Rüstung darunter. Die Auswahl einer Kategorie filtert das Raster auf diese Kategorie. Kategorien, die sich weiter aufteilen, listen ihre Teile bei Auswahl als dritte Ebene: Berufe nach Beruf, Rüstung nach Ausrüstungsplatz, Handelswaren nach Material. Umfasst gemeinsam deine Charakterbank und die Kriegshorte, sodass eine Kategorie alles zeigt, was du besitzt." -- TODO: confirmar termo oficial (warband/Kriegshorte)
L["Lists every group member against the consumables a raid expects -- flask, food, augment rune, vantus -- whenever a ready check starts, whoever started it."] = "Listet jedes Gruppenmitglied gegen die von einem Schlachtzug erwarteten Verbrauchsgüter auf -- Fläschchen, Essen, Verstärkungsrune, Vantus-Rune -- sobald ein Bereitschaftscheck startet, unabhängig davon, wer ihn gestartet hat."
L["Lists only the people something is actually wrong with, so a thirty-man roster becomes the three names you need to whisper. Someone whose client has not reported yet is not counted as missing."] = "Listet nur die Personen auf, bei denen tatsächlich etwas nicht stimmt, sodass aus einem 30-Mann-Aufgebot die drei Namen werden, die du anflüstern musst. Jemand, dessen Client noch nichts gemeldet hat, gilt nicht als fehlend."
