L["Not available while this bar is anchored to another element"] = "Nicht verfügbar, solange diese Leiste an einem anderen Element verankert ist"
L["Not currently talented"] = "Derzeit nicht talentiert"
L["Not overridable"] = "Nicht überschreibbar"
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies. Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = "Nicht überschreibbar. Diese Bedingungen sind gemeinsam genutzt und können nur geändert werden, solange keine Überschreibung bearbeitet wird. Eine Überschreibung ersetzt die Sichtbarkeitseinstellung vollständig -- Nie, Immer oder Mouseover -- und ignoriert alles, was hier festgelegt ist, während sie gilt. Mouseover ist auch für dieses Element fest vorgegeben: Sein Hover-Verhalten folgt der gemeinsamen Einstellung, eine Überschreibung könnte es höchstens dauerhaft sichtbar lassen."
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies."] = "Nicht überschreibbar. Diese Bedingungen sind gemeinsam genutzt und können nur geändert werden, solange keine Überschreibung bearbeitet wird. Eine Überschreibung ersetzt die Sichtbarkeitseinstellung vollständig -- Nie, Immer oder Mouseover -- und ignoriert alles, was hier festgelegt ist, während sie gilt."
L["Nothing Extra"] = "Nichts Zusätzliches"
L["November"] = true
L["Nudge the bubble up or down from where the game put it. Zero sits exactly on Blizzard's own position, which is already over the speaker's head."] = "Verschiebt die Sprechblase leicht nach oben oder unten von der Position, an die das Spiel sie gesetzt hat. Null entspricht genau Blizzards eigener Position, die bereits über dem Kopf des Sprechenden liegt."
L["OVERRIDES WARNING"] = "WARNUNG ZU ÜBERSCHREIBUNGEN"
L["October"] = true
L["Off (default): the cast bar fades with real transparency, matching the whole-frame Out of Range Alpha (best if you're colour-matching the frame and cast bar). On: the old behavior -- a black overlay dims the bar instead of fading it, which can't discolor a shielded/uninterruptible cast's tint but won't visually match the frame's fade."] = "Aus (Standard): Die Zauberleiste blendet mit echter Transparenz aus, passend zur „Transparenz außer Reichweite“ des gesamten Fensters (am besten, wenn du Fenster und Zauberleiste farblich abstimmst). An: das alte Verhalten -- ein schwarzes Overlay dunkelt die Leiste ab, statt sie auszublenden; dies kann die Einfärbung eines abgeschirmten/ununterbrechbaren Zaubers nicht verfälschen, passt aber optisch nicht zum Ausblenden des Fensters."
L["Offensive CDs"] = "Offensive Abklingzeiten"
L["Offsets the bottom row's icon size in pixels from Icon Scale. The top row keeps the base size."] = "Versetzt die Symbolgröße der unteren Zeile in Pixeln von der Symbolskalierung. Die obere Zeile behält die Grundgröße."
L["Offsets the top row's icon size in pixels from Icon Scale. The bottom row keeps the base size."] = "Versetzt die Symbolgröße der oberen Zeile in Pixeln von der Symbolskalierung. Die untere Zeile behält die Grundgröße."
L["On Cooldown"] = "In Abklingzeit"
L["On Hover"] = "Bei Mouseover"
L["On Icon"] = "Auf Symbol"
L["On"] = "An"
L["Once the lockout expires, show a Ready label on the icon in place of the countdown. The visibility rule above still applies."] = "Sobald die Sperre abläuft, wird auf dem Symbol die Beschriftung „Bereit“ anstelle des Countdowns angezeigt. Die obige Sichtbarkeitsregel gilt weiterhin."
L["Only Dispellable"] = "Nur Bannbare"
L["Only Open MenuOut of Combat."] = "Menü nur außerhalb des Kampfes öffnen."
L["Only Show for % Health"] = "Nur bei % Gesundheit anzeigen"
L["Only Tracked Auras"] = "Nur verfolgte Auren"
L["Only With Multiple Boss Frames"] = "Nur bei mehreren Boss-Fenstern"
L["Only affects the vertical (Right/Left Edge) positions"] = "Betrifft nur die vertikalen Positionen (rechte/linke Kante)"
L["Only applies when Name > Target is selected."] = "Gilt nur, wenn „Name > Ziel“ ausgewählt ist."
L["Only applies when Name or Name > Target is selected."] = "Gilt nur, wenn „Name“ oder „Name > Ziel“ ausgewählt ist."
L["Only applies when the selected text includes a Name."] = "Gilt nur, wenn der ausgewählte Text einen Namen enthält."
L["Only available when Portrait Mode is Detached"] = "Nur verfügbar, wenn der Porträtmodus „Losgelöst“ ist"
L["Only color at/above threshold"] = "Nur am/über dem Schwellenwert einfärben"
L["Only glow once the buff's stack count matches the comparison set via the gear."] = "Leuchtet erst, wenn die Stapelzahl des Buffs dem über das Zahnrad festgelegten Vergleich entspricht."
L["Only if Power Bar Hidden"] = "Nur wenn Ressourcenleiste ausgeblendet ist"
L["Only in Combat"] = "Nur im Kampf"
L["Only play alerts while in combat."] = "Warnungen nur im Kampf abspielen."
L["Only recolor the fill when more than one boss frame is active at once (a multi-boss phase). With a single boss frame up, it keeps its normal color even while targeted. Off (default) recolors regardless of how many boss frames are active."] = "Färbt die Füllung nur um, wenn mehr als ein Boss-Fenster gleichzeitig aktiv ist (eine Multi-Boss-Phase). Bei nur einem aktiven Boss-Fenster behält es seine normale Farbe, auch wenn es anvisiert ist. Aus (Standard) färbt unabhängig davon um, wie viele Boss-Fenster aktiv sind."
L["Only show debuffs whose full duration is at most this many seconds. Combines with the filters; Unlimited applies no cap."] = "Zeigt nur Debuffs, deren volle Dauer höchstens diese Anzahl an Sekunden beträgt. Kombiniert sich mit den Filtern; „Unbegrenzt“ wendet keine Obergrenze an."
L["Only show the cast bar while a cast is in progress; hide it the rest of the time."] = "Zeigt die Zauberleiste nur, während ein Zauber gewirkt wird; blendet sie die restliche Zeit aus."
L["Only show these buffs when you cast them."] = "Zeigt diese Buffs nur, wenn du sie wirkst."
L["Only shows the GCD circle while you are in combat."] = "Zeigt den GCD-Kreis nur, während du dich im Kampf befindest."
L["Only shows the cast bar circle while you are in combat."] = "Zeigt den Zauberleisten-Kreis nur, während du dich im Kampf befindest."
L["Only shows the cursor circle while you are in combat."] = "Zeigt den Cursor-Kreis nur, während du dich im Kampf befindest."
L["Only while AIRBORNE on a glide-capable mount or flight form. For the mount itself, ground included, use Skyriding Mount."] = "Nur, während du auf einem gleitfähigen Reittier oder in Flugform IN DER LUFT bist. Für das Reittier selbst, einschließlich am Boden, verwende „Himmelsreiten-Reittier“."
L["Only while airborne on a skyriding mount."] = "Nur, während du auf einem himmelsreitfähigen Reittier in der Luft bist."
L["Only works for Blizzard's whitelisted healer spell IDs (non-private auras)."] = "Funktioniert nur für Blizzards freigegebene Heiler-Zauber-IDs (nicht-private Auren)."
L["Only works outside of Instances"] = "Funktioniert nur außerhalb von Instanzen"
L["Opacity of the Button Overlay tint."] = "Deckkraft der Button-Overlay-Einfärbung."
L["Opacity of the background overlay. 0 removes it entirely; the 9.0.7 default is 62."] = "Deckkraft des Hintergrund-Overlays. 0 entfernt es vollständig; der 9.0.7-Standard ist 62."
L["Opacity of the bar fill; below 100 the world shows through the fill instead of the background."] = "Deckkraft der Leistenfüllung; unter 100 scheint die Welt durch die Füllung statt durch den Hintergrund."
L["Opacity of the resource fill; below 100 the world shows through the fill instead of the background."] = "Deckkraft der Ressourcenfüllung; unter 100 scheint die Welt durch die Füllung statt durch den Hintergrund."
L["Open Character Sheet"] = "Charakterblatt öffnen"
L["Open World Basic Coloring"] = "Basiseinfärbung offene Welt"
L["Open it anytime from Global Settings > Patch Notes."] = "Jederzeit über Globale Einstellungen > Patch-Notizen zu öffnen."
L["Opening Myslot again forces every bar visible, including bars using Match Any, Hide with Target or the mounted visibility conditions."] = "Erneutes Öffnen von Myslot erzwingt die Sichtbarkeit aller Leisten, einschließlich Leisten mit „Beliebige erfüllen“, „Mit Ziel ausblenden“ oder den Sichtbarkeitsbedingungen für Reittiere."
L["Opens"] = "Öffnet"
L["Order"] = "Reihenfolge"
L["Organizes your friends list into collapsible custom groups."] = "Organisiert deine Freundesliste in einklappbare, benutzerdefinierte Gruppen."
L["Out-of-range coloring now tracks the spell actually on the icon while a proc or talent override replaces it, instead of the base spell's range."] = "Die Reichweiten-Einfärbung folgt jetzt dem tatsächlich auf dem Symbol angezeigten Zauber, während ein Proc oder eine Talent-Überschreibung ihn ersetzt, statt der Reichweite des Basiszaubers."
L["Out-of-range frames darken instead of fading transparent, matching Blizzard's default party/raid frame look. Uses the same Out of Range Alpha % as brightness: 100% = no visible difference in/out of range, 10% = out-of-range frames drop to 10% brightness."] = "Fenster außerhalb der Reichweite werden abgedunkelt statt transparent ausgeblendet, passend zum Blizzard-Standard-Look von Gruppen-/Schlachtzugsfenstern. Verwendet dieselbe „Transparenz außer Reichweite“ % als Helligkeit: 100% = kein sichtbarer Unterschied in/außer Reichweite, 10% = Fenster außerhalb der Reichweite sinken auf 10% Helligkeit."
L["Outfit"] = "Outfit"
L["Outfits"] = "Outfits"
