L["Outline style override for all Cooldown Manager text. EUI Global Outline follows the global Outline Mode setting above."] = "Konturstil-Überschreibung für den gesamten Text des Abklingzeit-Managers. „EUI Globale Kontur“ folgt der obigen globalen Kontur-Modus-Einstellung."
