L["Outline style override for all Quality of Life text. EUI Global Outline follows the global Outline Mode setting above."] = "Konturstil-Überschreibung für den gesamten Quality-of-Life-Text. „EUI Globale Kontur“ folgt der obigen globalen Kontur-Modus-Einstellung."
L["Outline style override for all Quest Tracker text. EUI Global Outline follows the global Outline Mode setting above."] = "Konturstil-Überschreibung für den gesamten Text des Questverfolgers. „EUI Globale Kontur“ folgt der obigen globalen Kontur-Modus-Einstellung."
