L["Racial spells assigned to a custom bar stay there through spec changes and relogs, and racials untracked in Blizzard's Cooldown Manager display again."] = "Rasseneffekte, die einer benutzerdefinierten Leiste zugewiesen wurden, bleiben dort auch nach Spezialisierungswechseln und Neuanmeldungen erhalten, und im Abklingzeit-Manager von Blizzard nicht verfolgte Rasseneffekte werden wieder angezeigt."
