L["Raid frame absorbs and health ticks, nameplate health updates, tracking bar pairing and unit frame absorbs all do less work per event"] = "Absorptionen und Gesundheits-Ticks der Schlachtzugsfenster, Namensschild-Gesundheitsaktualisierungen, Trackingleisten-Zuordnung und Absorptionen der Einheitenfenster benötigen jetzt jeweils weniger Rechenaufwand pro Ereignis"
L["Raid frame buffs and debuffs are rebuilt for Midnight's new aura engine. Track whole spell categories with filters, then give each one its own display."] = "Buffs und Debuffs der Schlachtzugsfenster wurden für Midnights neue Auren-Engine überarbeitet. Verfolge ganze Zauberkategorien mit Filtern und gib jeder davon eine eigene Anzeige."
L["Raid only. Left-click the Durability column's header icon anytime to use the Auto-Hammer (item 132514) -- no one needs to be low first. When a player's Durability reading drops to 25% or below, their name blinks as a heads-up, but that's just a warning, not a requirement to click."] = "Nur im Schlachtzug. Klicke jederzeit mit links auf das Kopfzeilen-Symbol der Haltbarkeitsspalte, um den Auto-Hammer (Gegenstand 132514) zu verwenden -- niemand muss vorher niedrige Haltbarkeit haben. Sinkt der Haltbarkeitswert eines Spielers auf 25% oder darunter, blinkt dessen Name als Hinweis, aber das ist nur eine Warnung, kein Klickzwang."
L["Raid only. Left-click the Food column's header icon anytime to drop a feast at your own feet: Feast of Knowledge, falling back to Amani Cornucopia and then Loa's Gathering depending on what's in your bags. Disarmed while you already have a Well Fed buff active, so there's no wasted click."] = "Nur im Schlachtzug. Klicke jederzeit mit links auf das Kopfzeilen-Symbol der Essen-Spalte, um zu deinen eigenen Füßen ein Festmahl fallen zu lassen: Festmahl des Wissens, ansonsten Amani-Füllhorn und dann Loas Versammlung, je nachdem, was sich in deinen Taschen befindet. Deaktiviert, solange bereits ein „Gut genährt“-Buff aktiv ist, damit kein Klick verschwendet wird." -- TODO: confirmar termo oficial (Feast of Knowledge / Amani Cornucopia / Loa's Gathering)
