L["Recolor the bar while you have a buff. The first active buff in the list wins, so order = priority. Overrides threshold coloring while active.\nYou must be tracking the buff in Blizzard CDM, added to EUI CDM, and this only works with CDM trackable buffs."] = "Färbt die Leiste um, solange du einen Buff hast. Der erste aktive Buff in der Liste gewinnt, die Reihenfolge entspricht also der Priorität. Überschreibt die Schwellenwert-Einfärbung, während aktiv.\nDer Buff muss im Blizzard-CDM verfolgt und zum EUI-CDM hinzugefügt sein; dies funktioniert nur mit im CDM verfolgbaren Buffs."
L["Recolor the countdown text below Threshold Seconds."] = "Färbt den Countdown-Text unterhalb von „Schwellenwert Sekunden“ um."

