L["Replaces Buff Glow: the icon glows when its stack count matches the comparison below, using this spell's Buff Glow style (Modern WoW Glow if none is set)."] = "Ersetzt „Buff-Leuchten“: Das Symbol leuchtet, wenn seine Stapelzahl dem unten stehenden Vergleich entspricht, unter Verwendung des Buff-Leuchten-Stils dieses Zaubers (Modernes-WoW-Leuchten, falls keiner festgelegt ist)."
