L["Resource Aware CD Ready Glow may cause a slight loss in performance efficiency. Do you want to enable it?"] = "„Ressourcenbewusstes Abklingzeit-bereit-Leuchten“ kann die Leistung leicht beeinträchtigen. Möchtest du es aktivieren?"
