L["Resting"] = "Rastend"
L["Restyle Blizzard's chat bubbles for the channels you pick beside this.\n\nEllesmereUI keeps Blizzard's bubbles switched on and draws over them, so every bubble stays where the game put it, including the one over your own head. Nameplates are not involved and do not need to be visible.\n\nChannels you leave off keep Blizzard's own look."] = "Gestaltet Blizzards Chat-Sprechblasen für die daneben ausgewählten Kanäle neu.\n\nEllesmereUI lässt Blizzards Sprechblasen aktiviert und zeichnet darüber, sodass jede Sprechblase dort bleibt, wo das Spiel sie platziert hat, einschließlich der über deinem eigenen Kopf. Namensschilder sind nicht beteiligt und müssen nicht sichtbar sein.\n\nKanäle, die du nicht auswählst, behalten Blizzards eigenen Look."
L["Restyles Blizzard's on-screen progress bars (event objectives, nameplate counters) to the EUI look. Requires reload to apply.\n\nThese bars are drawn over rather than modified, so if the game ever reports their contents as protected the original bar is shown instead.\n\nUse the cog to set a minimum size, so bars on shrunken nameplates stay readable."] = "Gestaltet Blizzards Fortschrittsleisten auf dem Bildschirm (Ereignisziele, Namensschild-Zähler) im EUI-Look neu. Erfordert ein Neuladen, um wirksam zu werden.\n\nDiese Leisten werden übermalt statt verändert, daher wird die Originalleiste angezeigt, falls das Spiel deren Inhalt jemals als geschützt meldet.\n\nVerwende das Zahnrad, um eine Mindestgröße festzulegen, damit Leisten auf verkleinerten Namensschildern lesbar bleiben."
L["Reveal on hover only. Combines with the conditions below: hover-reveals while they all pass, stays hidden while any fails."] = "Erscheint nur bei Mouseover. Kombiniert sich mit den untenstehenden Bedingungen: erscheint bei Mouseover, solange alle erfüllt sind, bleibt ausgeblendet, solange eine davon nicht zutrifft."
L["Reverse the order of buttons on this bar."] = "Kehrt die Reihenfolge der Schaltflächen auf dieser Leiste um."
