L["Scales the custom tooltips shown by the unique minimap buttons (Great Vault, friends, calendar, mail, tracking)."] = "Skaliert die benutzerdefinierten Tooltips, die von den besonderen Minikarten-Schaltflächen angezeigt werden (Große Schatzkammer, Freunde, Kalender, Post, Tracking)."
