L["Scan all equipped gear costs at the Item Upgrade NPC.\n Scans each slot one at a time — this can take up to 10 seconds.\n Requires the Item Upgrade window to be open."] = "Scannt die Kosten aller angelegten Ausrüstungsgegenstände beim Gegenstandsaufwertungs-NSC.\n Scannt jeden Platz einzeln nacheinander — dies kann bis zu 10 Sekunden dauern.\n Erfordert, dass das Gegenstandsaufwertungs-Fenster geöffnet ist."
