L["Screen layer this bar renders on. Raise it to draw over other frames, lower it to sit behind them."] = "Bildschirmschicht, auf der diese Leiste dargestellt wird. Erhöhen, um über anderen Fenstern zu zeichnen, verringern, damit sie dahinter liegt."
