L["Seconds + GCD in Soul"] = "Sekunden + GCD in Seele"
L["Seconds Left"] = "Verbleibende Sekunden"
L["Seconds counts the time down in tenths. GCD Count counts whole global cooldowns instead, so inside Arcane Soul it reads as the number of Arcane Barrages that still fit, ending on a coloured LAST. Seconds + GCD in Soul mixes the two: tenths counting down to the window, Barrage count once it opens."] = "„Sekunden“ zählt die Zeit in Zehnteln herunter. „GCD-Anzahl“ zählt stattdessen ganze globale Abklingzeiten, sodass es innerhalb von Arkane Seele als Anzahl der noch passenden Arkanschauer angezeigt wird und mit einem farbigen LETZTER endet. „Sekunden + GCD in Seele“ vermischt beides: Zehntel zählen bis zum Fenster herunter, Schauer-Anzahl sobald es sich öffnet." -- TODO: confirmar termo oficial (Arcane Barrage)
L["Seconds left when threshold text starts (0 = off)"] = "Verbleibende Sekunden, ab denen der Schwellenwert-Text beginnt (0 = aus)"
L["Seconds of Arcane Surge left when the countdown appears. Always in seconds, including in GCD mode."] = "Verbleibende Sekunden von Arkaner Anstieg, wenn der Countdown erscheint. Immer in Sekunden, auch im GCD-Modus." -- TODO: confirmar termo oficial (Arcane Surge)
L["Seconds remaining below which Threshold Color and Threshold Decimals apply (0 = off)."] = "Verbleibende Sekunden, unterhalb derer „Schwellenwert-Farbe“ und „Schwellenwert-Dezimalstellen“ gelten (0 = aus)."
L["Seconds"] = "Sekunden"
