L["Show a 1-decimal countdown (2.7) below Threshold Seconds."] = "Zeigt unterhalb von „Schwellenwert Sekunden“ einen Countdown mit einer Dezimalstelle an (2.7)."
L["Show a 1-decimal countdown on presets and custom spell/item IDs when under the cog's Seconds Left threshold -- their active state on cooldown/utility bars, their buff duration on buff bars (both are hardcoded, so the remaining time is exact)."] = "Zeigt bei Vorlagen und benutzerdefinierten Zauber-/Gegenstands-IDs einen Countdown mit einer Dezimalstelle an, sobald der im Zahnrad festgelegte Schwellenwert „Verbleibende Sekunden“ unterschritten wird -- ihr aktiver Zustand auf Abklingzeit-/Hilfsleisten, ihre Buff-Dauer auf Buff-Leisten (beides ist fest codiert, daher ist die verbleibende Zeit exakt)."
L["Show a panel of equipped-gear sockets on the character sheet; click a socket to gem it."] = "Zeigt ein Fenster mit den Sockeln der angelegten Ausrüstung auf dem Charakterblatt; klicke einen Sockel an, um ihn zu bestücken."
L["Show a reminder when your active pet is set to Passive stance. Only applies to pet classes (Hunter, Warlock, Death Knight, Mage)."] = "Zeigt eine Erinnerung an, wenn dein aktiver Begleiter auf die Haltung „Passiv“ eingestellt ist. Gilt nur für Klassen mit Begleitern (Jäger, Hexenmeister, Todesritter, Magier)."
L["Show a tracked buff in this slot while it is active."] = "Zeigt einen verfolgten Buff in diesem Platz an, während er aktiv ist."
L["Show absorbs on Boss Frames, styled independently from the Boss tab's own Absorbs section."] = "Zeigt Absorptionen auf Boss-Fenstern, unabhängig vom eigenen Absorptions-Bereich des Boss-Reiters gestaltet."
L["Show every debuff in the base grid. The Base Filters dropdown is ignored while this is on."] = "Zeigt jeden Debuff im Basisraster an. Das Dropdown „Basisfilter“ wird ignoriert, solange dies aktiviert ist."
L["Show how many of the consumable you have left in your bags."] = "Zeigt an, wie viele des Verbrauchsguts sich noch in deinen Taschen befinden."
L["Show in Instances"] = "In Instanzen anzeigen"
L["Show item or spell tooltips when hovering reminder icons."] = "Zeigt Gegenstands- oder Zauber-Tooltips beim Überfahren von Erinnerungssymbolen an."
L["Show on Boss Frames"] = "Auf Boss-Fenstern anzeigen"
L["Show on Ready Check"] = "Bei Bereitschaftscheck anzeigen"
L["Show rune count in center and remove recharging text/animation"] = "Zeigt die Runenanzahl in der Mitte an und entfernt Text/Animation beim Aufladen"
L["Show special reminders while out in the open world.\nReminders are always hidden in rested areas (cities and inns)."] = "Zeigt besondere Erinnerungen in der offenen Welt an.\nErinnerungen bleiben in Erholungsgebieten (Städte und Gasthäuser) immer ausgeblendet."
L["Show the Mythic+ teleport section in the tooltip. Ready rows are click-to-teleport."] = "Zeigt den Mythisch-Plus-Teleport-Bereich im Tooltip an. Bereite Zeilen sind per Klick teleportierbar."
L["Show the Sated/Exhaustion lockout countdown on the icon."] = "Zeigt den Sperr-Countdown für Übersättigt/Erschöpfung auf dem Symbol an."
L["Show the border style and size controls for the timer bars."] = "Zeigt die Steuerelemente für Rahmenstil und -größe der Timer-Leisten an."
L["Show the bright spark at the leading edge of the cast bar fill."] = "Zeigt den hellen Funken an der Vorderkante der Zauberleisten-Füllung an."
L["Show the crafted quality rank on tracked items, matching the rank icon on the action bars. Items with no crafted quality are unaffected. Only shown while the item is owned."] = "Zeigt die Handwerksqualitätsstufe bei verfolgten Gegenständen an, passend zum Stufensymbol auf den Aktionsleisten. Gegenstände ohne Handwerksqualität sind davon nicht betroffen. Wird nur angezeigt, solange der Gegenstand im Besitz ist."
L["Show the enemy's raid target marker to the left of the spell name."] = "Zeigt die Schlachtzugs-Zielmarkierung des Gegners links vom Zaubernamen an."
L["Show the player's title inline with their name, and/or their guild on a line below it, on friendly nameplates."] = "Zeigt auf freundlichen Namensschildern den Titel des Spielers in einer Zeile mit dessen Namen und/oder seine Gilde in einer Zeile darunter an."
L["Show the resource text only while the power bar is hidden - disabled, filtered off for this spec, a spec with no power, or hidden by \"Hide Power Bar if Resource\". Off = always show the text."] = "Zeigt den Ressourcentext nur an, während die Ressourcenleiste ausgeblendet ist - deaktiviert, für diese Spezialisierung herausgefiltert, eine Spezialisierung ohne Ressource, oder ausgeblendet durch „Ressourcenleiste bei Ressource ausblenden“. Aus = Text immer anzeigen."
L["Show this indicator's buffs on every spec of your class, not only this spec."] = "Zeigt die Buffs dieses Indikators bei jeder Spezialisierung deiner Klasse an, nicht nur bei dieser Spezialisierung."
L["Show while this condition is false"] = "Anzeigen, solange diese Bedingung nicht zutrifft"
L["Show/Hide Windows Keybind"] = "Tastenbelegung Fenster anzeigen/ausblenden"
L["Shown on Modifier"] = "Bei Modifikator angezeigt"
L["Shows Sweeping Strikes charges on the resource bar; Unit Frames and the personal Nameplate show them regardless."] = "Zeigt Rundumschlag-Aufladungen auf der Ressourcenleiste an; Einheitenfenster und das persönliche Namensschild zeigen sie unabhängig davon an."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size, bar height and text offset."] = "Zeigt unterhalb des Warteschlangen-Annahme-Popups eine Countdown-Leiste an, die anzeigt, wie viel Zeit zum Annehmen bleibt. Funktioniert mit oder ohne das Redesign. Verwende die Farbfläche und das Zahnrad, um Countdown-Textfarbe, Textgröße, Leistenhöhe und Textversatz festzulegen."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size. bar height and text offset."] = "Zeigt unterhalb des Warteschlangen-Annahme-Popups eine Countdown-Leiste an, die anzeigt, wie viel Zeit zum Annehmen bleibt. Funktioniert mit oder ohne das Redesign. Verwende die Farbfläche und das Zahnrad, um Countdown-Textfarbe, Textgröße. Leistenhöhe und Textversatz festzulegen."
L["Shows a countdown to the Arcane Soul window over the last seconds of Arcane Surge, then the time left inside it. Sunfury Arcane Mages only."] = "Zeigt in den letzten Sekunden von Arkaner Anstieg einen Countdown bis zum Arkane-Seele-Fenster an, danach die verbleibende Zeit darin. Nur für Arkane Magier mit Sonnenzorn." -- TODO: confirmar termo oficial (Arcane Surge / Arcane Soul)
L["Shows a mana percentage row for every healer in your group as its own movable text display. Position it in Unlock Mode."] = "Zeigt für jeden Heiler in deiner Gruppe eine Mana-Prozent-Zeile als eigene verschiebbare Textanzeige an. Positioniere sie im Entsperrmodus."
L["Shows each crest's icon in front of its amount."] = "Zeigt das Symbol jedes Wappens vor dessen Anzahl an."
L["Shows every debuff on this frame."] = "Zeigt jeden Debuff auf diesem Fenster an."
L["Shows external defensives cast on you (Pain Suppression, Ironbark, etc.) in its own movable frame; position it via Unlock Mode."] = "Zeigt auf dich gewirkte externe Verteidigungszauber (Schmerzunterdrückung, Eisenrinde usw.) in einem eigenen verschiebbaren Fenster an; positioniere es über den Entsperrmodus."
L["Shows large amounts using K/M suffixes (284,208g becomes 284.2Kg) instead of the full grouped number. The tooltip always shows the exact amount."] = "Zeigt große Beträge mit K/M-Suffixen an (284.208g wird zu 284,2Kg) statt der vollständigen gruppierten Zahl. Der Tooltip zeigt immer den exakten Betrag an."
L["Shows only auras flagged for raid frames during combat"] = "Zeigt nur Auren an, die im Kampf für Schlachtzugsfenster markiert sind"
L["Shows only auras with a dispel type you can dispel"] = "Zeigt nur Auren mit einem Banntyp an, den du bannen kannst"
L["Shows only buffs that can be canceled"] = "Zeigt nur Buffs an, die abgebrochen werden können"
L["Shows only buffs you can spellsteal or purge"] = "Zeigt nur Buffs an, die du stehlen oder entfernen kannst"
L["Shows only debuffs Blizzard flags as important."] = "Zeigt nur Debuffs an, die Blizzard als wichtig markiert."
L["Shows only debuffs applied by bosses"] = "Zeigt nur von Bossen angewendete Debuffs an"
L["Shows only debuffs flagged for your role"] = "Zeigt nur für deine Rolle markierte Debuffs an"
L["Shows only priority debuffs"] = "Zeigt nur prioritäre Debuffs an"
L["Shows only the Buffs that appear on Raid Frames"] = "Zeigt nur die Buffs an, die auf Schlachtzugsfenstern erscheinen"
L["Shows only the Buffs you apply"] = "Zeigt nur die von dir angewendeten Buffs an"
L["Shows only the buffs you apply"] = "Zeigt nur die von dir angewendeten Buffs an"
L["Shows only the debuffs you apply that Blizzard also flags as important."] = "Zeigt nur die von dir angewendeten Debuffs an, die Blizzard zusätzlich als wichtig markiert."
L["Shows only the debuffs you apply."] = "Zeigt nur die von dir angewendeten Debuffs an."
L["Shows only this frame's Tracked Auras; add them with Edit Tracked Auras at the top of this menu."] = "Zeigt nur die verfolgten Auren dieses Fensters an; füge sie über „Verfolgte Auren bearbeiten“ oben in diesem Menü hinzu."
L["Shows the Role Check button in window layouts and enables Right Click: Role Check on Compact Band."] = "Zeigt die Schaltfläche „Rollenabfrage“ in Fensterlayouts an und aktiviert Rechtsklick: Rollenabfrage beim Kompaktband."
L["Shows the combat status text only while your character is in combat."] = "Zeigt den Kampfstatus-Text nur an, während sich dein Charakter im Kampf befindet."
L["Shows the debuff's dispel type icon (Magic, Curse, Disease, Poison, Bleed) on the bar."] = "Zeigt das Banntyp-Symbol des Debuffs (Magie, Fluch, Krankheit, Gift, Bluten) auf der Leiste an."
L["Shows the debuffs you apply plus important debuffs from anyone."] = "Zeigt die von dir angewendeten Debuffs sowie wichtige Debuffs von jedem an."
L["Shows the default Friends section for friends not in a custom group."] = "Zeigt den Standard-Freunde-Bereich für Freunde an, die sich in keiner benutzerdefinierten Gruppe befinden."
L["Shows the focus target's raid marker icon next to the cast bar itself, instead of (or in addition to) the frame-level marker in Extras."] = "Zeigt das Schlachtzugsmarkierungs-Symbol des Fokusziels neben der Zauberleiste selbst an, statt (oder zusätzlich zu) der Fenster-Markierung unter Extras."
L["Shows the overlay only for debuffs you can currently dispel."] = "Zeigt das Overlay nur für Debuffs an, die du derzeit bannen kannst."
L["Shows the ping mark on a member's frame when someone pings them (needs Blizzard's Show Pings on Raid Frames setting on)."] = "Zeigt die Ping-Markierung auf dem Fenster eines Mitglieds an, wenn jemand es anpingt (erfordert Blizzards Einstellung „Pings auf Schlachtzugsfenstern anzeigen“)."
L["Shows the plugin's own icon next to its text."] = "Zeigt das eigene Symbol des Plugins neben dessen Text an."
L["Shows the plugin's text. Off leaves an icon-only block that still carries the plugin's tooltip and clicks."] = "Zeigt den Text des Plugins an. Aus lässt einen reinen Symbol-Block übrig, der weiterhin den Tooltip und die Klicks des Plugins trägt."
L["Shows the spec icon next to the text."] = "Zeigt das Spezialisierungssymbol neben dem Text an."
L["Shows the window even when you can do nothing about what it reports. Every column is read from your own client, so this view is complete rather than degraded."] = "Zeigt das Fenster auch dann an, wenn du nichts gegen die gemeldeten Inhalte tun kannst. Jede Spalte wird von deinem eigenen Client gelesen, daher ist diese Ansicht vollständig statt eingeschränkt."
L["Shows your best split on upcoming bosses instead of only killed ones."] = "Zeigt deine beste Split-Zeit bei kommenden Bossen an, statt nur bei bereits besiegten."
