L["Sizes the movement alert's free text, bar number and icon countdown. Switching the alert's Display Mode re-seeds this value."] = "Legt die Größe von Freitext, Leistennummer und Symbol-Countdown der Bewegungswarnung fest. Ein Wechsel des Anzeigemodus der Warnung setzt diesen Wert zurück."
