L["Smallest on-screen size a reskinned bar is drawn at.\n\nWidget bars on a nameplate inherit that nameplate's scale, so they come out tiny on small units. Below this size the bar is scaled up instead, text and all.\n\nSet to 0 to mirror Blizzard's size exactly."] = "Kleinste Bildschirmgröße, in der eine neu gestaltete Leiste dargestellt wird.\n\nWidget-Leisten auf einem Namensschild übernehmen dessen Skalierung und erscheinen daher bei kleinen Einheiten winzig. Unterhalb dieser Größe wird die Leiste stattdessen vergrößert, Text eingeschlossen.\n\nAuf 0 setzen, um Blizzards Größe exakt zu übernehmen."
