L["Spec and conditional overrides can now hold the Visibility setting itself, replacing it with Never, Always or Mouseover for those specs."] = "Spezialisierungs- und bedingte Überschreibungen können jetzt die Sichtbarkeitseinstellung selbst enthalten und sie für diese Spezialisierungen durch „Nie“, „Immer“ oder „Mouseover“ ersetzen."
