L["Split Stack"] = "Stapel teilen"
L["Split items by category -- Armor, Consumables, Professions and so on -- using the same category list, order and renames as the All Items bag view. Nests inside the expansion headers when Nest by Expansion is also on. Categories that split further do so automatically: gear by equipment slot, Professions and Trade Goods by profession and material type."] = "Teilt Gegenstände nach Kategorie auf -- Rüstung, Verbrauchsgüter, Berufe und so weiter -- unter Verwendung derselben Kategorieliste, Reihenfolge und Umbenennungen wie die Taschenansicht „Alle Gegenstände“. Verschachtelt sich innerhalb der Erweiterungs-Kopfzeilen, wenn „Nach Erweiterung verschachteln“ ebenfalls aktiviert ist. Kategorien, die sich weiter aufteilen, tun dies automatisch: Ausrüstung nach Ausrüstungsplatz, Berufe und Handelswaren nach Beruf und Materialtyp."
L["Split this stack into empty slots repeatedly until only the chosen amount or less remains. Alt+Enter does the same."] = "Teilt diesen Stapel wiederholt auf leere Plätze auf, bis nur noch die gewählte Menge oder weniger übrig bleibt. Alt+Eingabe bewirkt dasselbe."
L["Square or Rectangular Shape"] = "Quadratische oder rechteckige Form"
