L["Stack Splitter"] = "Stapel-Teiler"
L["Stack Text Color"] = "Stapeltext-Farbe"
L["Stack Text and Glows"] = "Stapeltext und Leuchten"
L["Stack Thresholds"] = "Stapel-Schwellenwerte"
L["Stagger Full %"] = "Staffelung voll %"
L["Stamps system messages, loot, achievements, and addon prints, not just player chat"] = "Versieht Systemnachrichten, Beute, Erfolge und Addon-Ausgaben mit Zeitstempeln, nicht nur den Spieler-Chat"
L["Standalone Timer Size"] = "Eigenständige-Timer-Größe"
L["Star"] = "Stern"
L["Starfire"] = "Sternenfeuer"
L["Status Icon"] = "Statussymbol"
L["Status Text Size"] = "Status-Textgröße"
L["Steady Shot"] = "Stetiger Schuss"
L["Stealable"] = "Stehlbar"
L["Steering"] = "Lenkung"
L["Stop pull timer"] = "Pull-Timer stoppen"
L["Strata Level"] = "Ebenenstufe"
L["Strict Comparison Mode"] = "Strikter Vergleichsmodus"
L["Strip Colors"] = "Farben entfernen"
L["Style each filter: icon rows, glows, bars, health color"] = "Gestalte jeden Filter individuell: Symbolzeilen, Leuchten, Leisten, Gesundheitsfarbe"
L["Style to apply to every window below."] = "Stil, der auf jedes Fenster unten angewendet wird."
L["Style"] = "Stil"
L["Subzone Text Color"] = "Unterzonentext-Farbe"
L["Summon Infernal\n(Cursor)"] = "Inferno beschwören\n(Cursor)"
L["Summon"] = "Beschwören"
L["Sunday"] = true
L["Suppresses \"You have learned a new spell/ability/passive effect\" and \"You have unlearned ...\" system messages, like the ones spammed every time you switch spec or talent loadout."] = "Unterdrückt die Systemmeldungen „Du hast einen neuen Zauber/eine neue Fähigkeit/einen neuen Passiveffekt erlernt“ und „Du hast … verlernt“, wie sie bei jedem Wechsel der Spezialisierung oder Talentausrüstung gespammt werden."
L["Suppresses right click targeting. Enemies applies everywhere. Allies In Combat only suppresses friendly targets while you are in combat, so you can still right click vendors and NPCs out of combat.\n\nNote: while this is active, holding Left+Right click to move forward won't work if your cursor is over a suppressed nameplate/unit, since this feature has to take over the right mouse button entirely to block targeting."] = "Unterdrückt das Anvisieren per Rechtsklick. „Gegner“ gilt überall. „Verbündete im Kampf“ unterdrückt freundliche Ziele nur, während du dich im Kampf befindest, sodass du außerhalb des Kampfes weiterhin Händler und NSCs per Rechtsklick anklicken kannst.\n\nHinweis: Während dies aktiv ist, funktioniert das Gedrückthalten von Links+Rechtsklick zum Vorwärtsbewegen nicht, wenn sich dein Cursor über einem unterdrückten Namensschild/einer Einheit befindet, da diese Funktion die rechte Maustaste vollständig übernehmen muss, um das Anvisieren zu blockieren."
L["Swap Light/Reckless Pots When Missing"] = "Licht-/Tollkühnheits-Tränke bei Fehlen tauschen"
L["Sweeping Strikes"] = "Rundumschlag"
L["Switch Blizzard's chat bubbles off for as long as you are inside a dungeon, raid, scenario or battleground, and back on the way out.\n\nEllesmereUI never restyles bubbles inside an instance: the game's bubble frames are off limits to addons there. This decides whether Blizzard's own are visible at all."] = "Schaltet Blizzards Chat-Sprechblasen aus, solange du dich in einem Dungeon, Schlachtzug, Szenario oder Schlachtfeld befindest, und wieder ein, sobald du es verlässt.\n\nEllesmereUI gestaltet Sprechblasen innerhalb einer Instanz niemals neu: Die Sprechblasen-Fenster des Spiels sind dort für Addons tabu. Dies entscheidet nur, ob Blizzards eigene überhaupt sichtbar sind."
L["Switch to Experience"] = "Zu Erfahrung wechseln"
L["Switch to Reputation"] = "Zu Ruf wechseln"
L["Synced with Simple Mode"] = "Mit einfachem Modus synchronisiert"
L["TARGET AND FOCUS EFFECTS"] = "ZIEL- UND FOKUS-EFFEKTE"
L["THIRD-PARTY ADDONS"] = "DRITTANBIETER-ADDONS"
L["THRESHOLD TEXT"] = "SCHWELLENWERT-TEXT"
L["TTS Message"] = "TTS-Nachricht"
L["Tab Visibility"] = "Reiter-Sichtbarkeit"
L["Talent gating is only available while playing this spec's class"] = "Talent-Sperrung ist nur verfügbar, während du die Klasse dieser Spezialisierung spielst"
L["Talent"] = "Talent"
L["Talents & Spellbook"] = "Talente & Zauberbuch"
L["Tar Trap\n(Cursor)"] = "Teerfalle\n(Cursor)"
L["Target Absorb Style"] = "Ziel-Absorptionsstil"
L["Target Bar Texture"] = "Ziel-Leistentextur"
L["Target Border Size"] = "Ziel-Rahmengröße"
L["Target Cast Bar Name Size"] = "Ziel-Zauberleisten-Namensgröße"
L["Target Cast Bar Target Size"] = "Ziel-Zauberleisten-Zielgröße"
L["Target Cast Bar Texture"] = "Ziel-Zauberleisten-Textur"
L["Target Cast Bar Timer Size"] = "Ziel-Zauberleisten-Timer-Größe"
L["Target Distance Text Size"] = "Zielentfernungstext-Größe"
L["Target Fill Color"] = "Ziel-Füllfarbe"
L["Target Heal Absorb Style"] = "Ziel-Heilabsorptionsstil"
L["Target, Focus and Targeted Spell cast bars no longer truncate spell names when there is no target text sharing the bar."] = "Zauberleisten für Ziel, Fokus und anvisierten Zauber schneiden Zaubernamen nicht mehr ab, wenn kein Zieltext die Leiste teilt."
L["Targeted Bars Name Size"] = "Anvisierte-Leisten-Namensgröße"
L["Targeted Bars Target Size"] = "Anvisierte-Leisten-Zielgröße"
L["Targeted Bars Texture"] = "Anvisierte-Leisten-Textur"
L["Targeted Bars Timer Size"] = "Anvisierte-Leisten-Timer-Größe"
L["Targeting:"] = "Anvisiert:"
L["Teleport Home"] = "Nach Hause teleportieren"
L["TellMeWhen"] = true
L["Temple of Sethraliss"] = "Tempel der Sethraliss" -- TODO: confirmar termo oficial
L["Terrifying Roar"] = "Furchterregendes Brüllen" -- TODO: confirmar termo oficial
L["Text Growth"] = "Textwachstum"
L["Text Offset Y"] = "Text-Versatz Y"
L["Text Scale (per data bar)"] = "Textskalierung (pro Datenleiste)"
L["Text Wrap"] = "Textumbruch"
L["Text X"] = "Text X"
L["Text Y"] = "Text Y"
L["Texture Not Found"] = "Textur nicht gefunden"
L["Texture for the health, power and class resource bars."] = "Textur für Gesundheits-, Ressourcen- und Klassenressourcenleisten."
L["Textures"] = "Texturen"
L["That setting is stored by list position and can't be safely overridden."] = "Diese Einstellung wird nach Listenposition gespeichert und kann nicht sicher überschrieben werden."
L["The Battle.net friend online and offline toast gets a window skin, with its own Friend Notifications card"] = "Die Battle.net-Benachrichtigung für online/offline gehende Freunde erhält einen Fenster-Skin mit eigener Karte unter Freundesbenachrichtigungen"
L["The Battle.net popup when a friend comes online or goes offline, plus broadcasts and invites."] = "Das Battle.net-Popup, wenn ein Freund online oder offline geht, sowie Statusmeldungen und Einladungen."
L["The Blinding Vale"] = "Das Blendende Tal" -- TODO: confirmar termo oficial
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "Der Abklingzeit-Manager kann weit mehr, als nur Abklingzeiten anzuzeigen -- er bietet auch Einstellungen pro Zauber, Leisten-Leuchten, Trackingleisten und mehr! Wirf einen Blick auf einige Tipps und Tricks, um mehr daraus zu machen."
L["The Hunt\n(Focus)"] = "Die Jagd\n(Fokus)"
L["The LFG Reminder popup now matches dungeon names on every client language, not only English and Russian."] = "Das Gruppensuche-Erinnerung-Popup gleicht Dungeon-Namen jetzt in jeder Client-Sprache ab, nicht nur Englisch und Russisch."
L["The Missing Pet reminder no longer appears while mounted or flashes on dismount."] = "Die Erinnerung „Fehlendes Begleitwesen“ erscheint nicht mehr, während du beritten bist, und blinkt nicht mehr beim Absteigen."
L["The Venomous Abyss"] = "Der Giftige Abgrund" -- TODO: confirmar termo oficial
L["The Whirlwind and Sweeping Strikes bar honors the Empty Bar Overlay again so spent charges show in Dark Mode, no longer draws a second set of divider lines with Bar Spacing set, hides its threshold strip while thresholds are disabled, and accepts a stack threshold up to 20."] = "Die Leiste für Wirbelwind und Rundumschlag berücksichtigt wieder das Overlay für leere Leisten, sodass verbrauchte Aufladungen im Dunkelmodus angezeigt werden, zeichnet bei gesetztem Leistenabstand keinen zweiten Satz Trennlinien mehr, blendet ihren Schwellenwert-Streifen aus, solange Schwellenwerte deaktiviert sind, und akzeptiert einen Stapel-Schwellenwert bis 20."
L["The active override's Buff Manager is bound to the open page. Leave the Buff Manager tab to switch overrides."] = "Der Buff-Manager der aktiven Überschreibung ist an die geöffnete Seite gebunden. Verlasse den Reiter „Buff-Manager“, um die Überschreibung zu wechseln."
L["The active override's custom Buff Manager is bound to this page. Leave the Buff Manager tab to switch to another override."] = "Der benutzerdefinierte Buff-Manager der aktiven Überschreibung ist an diese Seite gebunden. Verlasse den Reiter „Buff-Manager“, um zu einer anderen Überschreibung zu wechseln."
L["The bank window catches up to the bags: nest OneBank and OneWarbank by expansion, group items by your bag categories with automatic splits by equipment slot, profession and material, and browse a category sidebar that spans your character bank and warband together."] = "Das Bankfenster zieht mit den Taschen gleich: OneBank und OneWarbank verschachteln sich nach Erweiterung, Gegenstände werden nach deinen Taschenkategorien gruppiert mit automatischer Aufteilung nach Ausrüstungsplatz, Beruf und Material, und eine Kategorie-Seitenleiste durchsucht gemeinsam deine Charakterbank und die Kriegshorte."
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "Genau das Gegenteil von Himmelsreiten (in der Luft): alles, was nicht in der Luft auf einem gleitfähigen Reittier oder in Flugform ist, einschließlich am Boden stehend."
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "Die Überschreibungsgruppe „%s“ stellt bereits den benutzerdefinierten Entsperrmodus für deine aktuelle Spezialisierung bereit. Passe ihn dort an, oder entferne diese Spezialisierung aus dieser Gruppe."
L["The pasted string could not be read completely. Please paste it again."] = "Die eingefügte Zeichenfolge konnte nicht vollständig gelesen werden. Bitte füge sie erneut ein."
L["The pet frame updates its name and portrait when you swap pets (for example Voidwalker to Felhunter)."] = "Das Begleiterfenster aktualisiert Name und Porträt, wenn du den Begleiter wechselst (zum Beispiel von Leerwandler zu Teufelsjäger)."
L["The refresh rate now bottoms out at 0.5s (lower saved values move up to it), trimming memory churn during combat."] = "Die Aktualisierungsrate liegt jetzt minimal bei 0,5s (niedrigere gespeicherte Werte werden darauf angehoben), was den Speicher-Overhead im Kampf verringert."
L["The scriptProfile CVar is enabled."] = "Die CVar „scriptProfile“ ist aktiviert."
L["The single stack threshold is off while Multiple Thresholds is on."] = "Der einzelne Stapel-Schwellenwert ist deaktiviert, solange „Mehrere Schwellenwerte“ aktiviert ist."
L["The stricter in-combat subset of the raid set."] = "Die strengere Kampf-Teilmenge des Schlachtzugs-Sets."
L["The taintLog CVar is enabled."] = "Die CVar „taintLog“ ist aktiviert."
L["The taintLog and scriptProfile CVars are enabled."] = "Die CVars „taintLog“ und „scriptProfile“ sind aktiviert."
L["The target effect's border size no longer snaps back to normal while a cast bar is shown with Border Wraps Around Cast Bar enabled."] = "Die Rahmengröße des Zieleffekts springt nicht mehr auf normal zurück, während eine Zauberleiste mit aktiviertem „Rahmen umschließt Zauberleiste“ angezeigt wird."
L["Themed Blizzard frames: Character Sheet, tooltips, menus, popups, Dragon Riding HUD."] = "Gestaltete Blizzard-Fenster: Charakterblatt, Tooltips, Menüs, Popups, Drachenreiten-HUD."
L["These are the same settings found on each module's own pages, not separate ones."] = "Dies sind dieselben Einstellungen, die auf den eigenen Seiten jedes Moduls zu finden sind, keine separaten."
L["Thickness applies to Solid Border and Pixel Glow"] = "Dicke gilt für „Durchgezogener Rahmen“ und „Pixel-Leuchten“"
L["Thickness in physical pixels for Solid Border and Pixel Glow."] = "Dicke in physischen Pixeln für „Durchgezogener Rahmen“ und „Pixel-Leuchten“."
L["Thickness in physical pixels. -1 follows the Debuff Manager's Border setting, 0 hides the dispel color border."] = "Dicke in physischen Pixeln. -1 folgt der Rahmeneinstellung des Debuff-Managers, 0 blendet den Bannfarben-Rahmen aus."
L["Thickness of the Pixel Glow applied to this bar's buff icons."] = "Dicke des Pixel-Leuchtens, das auf die Buff-Symbole dieser Leiste angewendet wird."
L["This Setting Has Overrides"] = "Diese Einstellung hat Überschreibungen"
L["This bar will always be attached to your current target's nameplate"] = "Diese Leiste wird immer am Namensschild deines aktuellen Ziels angeheftet"
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "Dies kann nicht ändern, welche Zauber der Nutzer im Blizzard-CDM verfolgt.\nEs wird empfohlen, zusätzlich dein Blizzard-CDM-Layout für jede hier ausgewählte Spezialisierung zu teilen."
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Dies kann nicht rückgängig gemacht werden. Erwäge, dieses Profil zuerst als Sicherung zu exportieren."
L["This condition is coming in a future update."] = "Diese Bedingung folgt in einem zukünftigen Update."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "Diese Bedingung ist derzeit nicht aktiv. Erfülle zuerst eine ihrer Bedingungen (zum Beispiel den Dungeon betreten), damit du das Layout in seinem tatsächlichen Kontext anordnen kannst."
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "Dieses Element erscheint, sobald EINE Anzeigen-Bedingung zutrifft. Ausblenden behält seine Bedeutung in beiden Abgleichmodi: ein aktiviertes Ausblenden blendet immer aus, in jeder Zeile."
L["This element shows as soon as ONE condition matches, and a Hide lane then means show while that condition is false."] = "Dieses Element erscheint, sobald EINE Bedingung zutrifft, und eine Ausblenden-Zeile bedeutet dann, es anzuzeigen, solange diese Bedingung nicht zutrifft."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "Diese Funktion optimiert deine Grafikeinstellungen im Spiel für die beste Kombination aus hoher FPS-Zahl und visueller Klarheit.\n\nDu kannst alle Änderungen jederzeit rückgängig machen, indem du auf „Meine Einstellungen wiederherstellen“ klickst, das nach der Optimierung erscheint.\n\n\nWas wir ändern:\n\n"
L["This frame's source changes require a UI reload to take effect."] = "Änderungen an der Quelle dieses Fensters erfordern ein UI-Neuladen, damit sie wirksam werden."
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "Der benutzerdefinierte Buff-Manager dieser Gruppe kann nur aktiviert oder bearbeitet werden, während du eine ihrer Spezialisierungen spielst."
L["This is a voice preview"] = "Dies ist eine Stimmvorschau"
L["This is the spec you're syncing from -- it's always included."] = "Dies ist die Spezialisierung, von der aus du synchronisierst -- sie ist immer eingeschlossen."
L["This module can't be overridden. Exit the override editing session to open it."] = "Dieses Modul kann nicht überschrieben werden. Verlasse die Überschreibungs-Bearbeitungssitzung, um es zu öffnen."
L["This module is excluded from Spec Overrides."] = "Dieses Modul ist von Spezialisierungs-Überschreibungen ausgeschlossen."

-- == Batch 2026-09-16 (missing_deDE.txt lines 2071-2330) ==
L["This option is only available for abilities with multiple charges"] = "Diese Option ist nur für Fähigkeiten mit mehreren Aufladungen verfügbar"
L["This option requires <text> to be enabled"] = "Diese Option erfordert, dass <text> aktiviert ist"
L["This option requires Blizzard's Assisted Highlight to be enabled"] = "Diese Option erfordert, dass Blizzards unterstützte Hervorhebung aktiviert ist"
L["This option requires Combine Spell Name and Target to be disabled."] = "Diese Option erfordert, dass „Zaubername und Ziel kombinieren“ deaktiviert ist."
L["This option requires Countdown Format to count GCDs inside Arcane Soul"] = "Diese Option erfordert, dass das Countdown-Format innerhalb von Arkane Seele GCDs zählt"
L["This option requires Dark Mode Class Resource to be disabled. Dark Mode colors can be adjusted in Global Settings -> Fonts & Colors."] = "Diese Option erfordert, dass „Dunkelmodus-Klassenressource“ deaktiviert ist. Dunkelmodus-Farben können unter Globale Einstellungen -> Schriftarten & Farben angepasst werden."
L["This option requires Split Compare to include a key level"] = "Diese Option erfordert, dass „Split-Vergleich“ eine Schlüsselstein-Stufe einschließt"
L["This option requires Tooltips to be set to Shown on Modifier"] = "Diese Option erfordert, dass Tooltips auf „Bei Modifikator angezeigt“ eingestellt sind"
L["This option requires a Split Compare mode"] = "Diese Option erfordert einen Split-Vergleichsmodus"
L["This option requires a cooldown-tracking bar"] = "Diese Option erfordert eine Abklingzeit-Trackingleiste"
L["This option requires a style that draws the glow ring"] = "Diese Option erfordert einen Stil, der den Leuchtring zeichnet"
L["This option requires the Button Overlay style"] = "Diese Option erfordert den Stil „Button-Overlay“"
L["This overwrites the chosen frame's current settings. Frame position, visibility, and enable state are not changed."] = "Dies überschreibt die aktuellen Einstellungen des gewählten Fensters. Fensterposition, Sichtbarkeit und Aktivierungsstatus werden nicht geändert."
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Dies überschreibt die aktuellen Einstellungen dieses Fensters. Fensterposition, Sichtbarkeit und Aktivierungsstatus werden nicht geändert."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Dies überschreibt die Einstellungen dieses Profils dauerhaft mit der Überschreibung „%s“: ihre erfassten Einstellungen sowie ihre benutzerdefinierten Entsperrmodus- und Buff-Manager-Layouts (sofern vorhanden) werden zur eigenen Basis des Profils für jede Spezialisierung. ALLE Spezialisierungs-Überschreibungsgruppen dieses Profils werden anschließend gelöscht, und die Oberfläche wird neu geladen. Bedingte Überschreibungen sind davon nicht betroffen."
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Diese Profil-Zeichenfolge enthält keine Einstellungen für Fenster- & Tooltip-Skins."
L["This profile string does not carry any override data."] = "Diese Profil-Zeichenfolge enthält keine Überschreibungsdaten."
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Dieses Profil wurde bei %1$d%% UI-Skalierung erstellt; deine ist %2$d%%. Deine UI-Skalierung an das importierte Profil anpassen? Dies zeigt alle Profile in dieser Skalierung an, da die UI-Skalierung keine profilbezogene Einstellung ist, kann aber jederzeit wieder auf deinen ursprünglichen Wert zurückgesetzt werden."
L["This replaces %d existing value(s) for this setting across your specs. Do you want to continue?"] = "Dies ersetzt %d vorhandene(n) Wert(e) für diese Einstellung über deine Spezialisierungen hinweg. Möchtest du fortfahren?"
L["This replaces %d existing value(s) for this setting across your specs."] = "Dies ersetzt %d vorhandene(n) Wert(e) für diese Einstellung über deine Spezialisierungen hinweg."
L["This replaces %d existing value(s) for this setting on this bar. Do you want to continue?"] = "Dies ersetzt %d vorhandene(n) Wert(e) für diese Einstellung auf dieser Leiste. Möchtest du fortfahren?"
L["This replaces %d existing value(s) for this setting on this bar."] = "Dies ersetzt %d vorhandene(n) Wert(e) für diese Einstellung auf dieser Leiste."
L["This replaces 3 existing value(s) for this setting across your specs. Do you want to continue?"] = "Dies ersetzt 3 vorhandene Werte für diese Einstellung über deine Spezialisierungen hinweg. Möchtest du fortfahren?"
L["This setting already has an override for %s"] = "Diese Einstellung hat bereits eine Überschreibung für %s"
L["This setting can't be overridden."] = "Diese Einstellung kann nicht überschrieben werden."
L["This setting's active Apply to Bar (All Specs) value will be replaced."] = "Der aktive Wert von „Auf Leiste anwenden (alle Spezialisierungen)“ dieser Einstellung wird ersetzt."
L["This setting's active Apply to Bar value will be replaced."] = "Der aktive Wert von „Auf Leiste anwenden“ dieser Einstellung wird ersetzt."
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "Der benutzerdefinierte Entsperrmodus dieser Spezialisierung gehört zu „%s“. Passe ihn dort an, oder entferne die Spezialisierung aus dieser Gruppe."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Diese Einheit verwendet das Blizzard-Standardfenster -- hier gibt es keine EllesmereUI-Einstellungen zu konfigurieren."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "Das Fenster dieser Einheit ist ausgeblendet -- hier gibt es keine EllesmereUI-Einstellungen zu konfigurieren."
L["This will create a fully unique Buff Manager for this conditional group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect it."] = "Dies erstellt einen vollständig eigenständigen Buff-Manager für diese bedingte Gruppe. Deine aktuellen Buff-Manager-Einstellungen werden als Ausgangspunkt kopiert, und Änderungen an deinem Standard-Buff-Manager wirken sich nicht mehr darauf aus."
L["This will create a fully unique Buff Manager for this override group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect these specs."] = "Dies erstellt einen vollständig eigenständigen Buff-Manager für diese Überschreibungsgruppe. Deine aktuellen Buff-Manager-Einstellungen werden als Ausgangspunkt kopiert, und Änderungen an deinem Standard-Buff-Manager wirken sich nicht mehr auf diese Spezialisierungen aus."
L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "Dies erstellt einen vollständig eigenständigen Entsperrmodus für diese bedingte Gruppe. Änderungen an deinem Standard-Entsperrmodus wirken sich nicht mehr darauf aus."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "Dies erstellt einen vollständig eigenständigen Entsperrmodus für diese Überschreibungsgruppe. Änderungen an deinem Standard-Entsperrmodus wirken sich nicht mehr auf diese Spezialisierungen aus."
L["This will display ALL of your debuffs on enemy nameplates, rather than only the important ones."] = "Dies zeigt ALLE deine Debuffs auf gegnerischen Namensschildern an, statt nur die wichtigen."
L["This will keep appearing each login until the layout is correct."] = "Dies erscheint bei jedem Login weiterhin, bis das Layout korrekt ist."
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Dies ersetzt DEINE Blizz-UI-Enhanced-Einstellungen (die Reiter Fenster-Skins und Tooltips, Menüs & Popups) durch die des Teilenden, über ALLE deine Profile hinweg. Deine aktuellen Einstellungen auf diesen beiden Reitern können danach nicht wiederhergestellt werden."
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Custom bars are not affected. Continue?"] = "Dies setzt alle Standard-Zauberzuweisungen der Leisten für die aktuelle Spezialisierung zurück, um dem Blizzard-CDM-Layout zu entsprechen. Benutzerdefinierte Leisten sind davon nicht betroffen. Fortfahren?"
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Spells you added yourself (presets, custom IDs and racials) are kept. Continue?"] = "Dies setzt alle Standard-Zauberzuweisungen der Leisten für die aktuelle Spezialisierung zurück, um dem Blizzard-CDM-Layout zu entsprechen. Selbst hinzugefügte Zauber (Vorlagen, benutzerdefinierte IDs und Rasseneffekte) bleiben erhalten. Fortfahren?"
