L["Uncheck a spec to remove it from the sync. Removed specs keep their current trinkets, pots, racials & buff presets."] = "Deaktiviere eine Spezialisierung, um sie aus der Synchronisierung zu entfernen. Entfernte Spezialisierungen behalten ihre aktuellen Schmuckstücke, Tränke, Rasseneffekte & Buff-Vorlagen."
