L["Uses Blizzard's own party switch, independent of the other channels. Instance chat, the one an LFG or LFR group talks in, is covered here too."] = "Verwendet Blizzards eigenen Gruppen-Schalter, unabhängig von den anderen Kanälen. Instanz-Chat, in dem eine Gruppensuche- oder Zufallsschlachtzug-Gruppe spricht, ist hier ebenfalls abgedeckt."
L["Uses Blizzard's own raid switch, which it ships off. Ticking this turns that switch on, and it is put back the way you had it when you untick it or switch the feature off."] = "Verwendet Blizzards eigenen Schlachtzugs-Schalter, der standardmäßig deaktiviert ausgeliefert wird. Das Aktivieren dieser Option schaltet ihn ein, und er wird wieder in den vorherigen Zustand versetzt, wenn du die Option deaktivierst oder die Funktion abschaltest."
