L["What sits between the crest amounts."] = "Was zwischen den Wappen-Beträgen steht."
L["What sits in front of the number. Icon shows the character icon; the color swatches on the left tint it."] = "Was vor der Zahl steht. „Symbol“ zeigt das Charaktersymbol; die Farbflächen links färben es ein."
L["When enabled, nameplates stack vertically instead of overlapping."] = "Wenn aktiviert, stapeln sich Namensschilder vertikal, statt sich zu überlappen."
L["When on, augment rune/flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Wenn aktiviert, werden Erinnerungen für Verstärkungsrune/Fläschchen/Essen/Waffe weiterhin (abgedunkelt) angezeigt, wenn du keinen passenden Gegenstand in deinen Taschen hast, als Hinweis zum Nachkaufen.\nWenn deaktiviert, werden sie vollständig ausgeblendet, wenn du den Gegenstand nicht bei dir trägst."
L["Whenever not airborne on a skyriding mount."] = "Immer wenn du nicht auf einem himmelsreitfähigen Reittier in der Luft bist."
L["Which end of the crest ladder comes first."] = "Welches Ende der Wappen-Stufenleiter zuerst kommt."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Only Dispellable shows just the buffs that can be dispelled, purged or soothed. With a Dispel Glow style set, every dispellable buff shown glows."] = "Welche gegnerischen Buffs auf Namensschildern angezeigt werden. „Wichtig“ zeigt die von Blizzard für gegnerische Namensschilder markierten Buffs sowie alles Bannbare an; „Nur Bannbare“ zeigt nur die Buffs, die gebannt, entfernt oder besänftigt werden können. Bei festgelegtem Bann-Leuchten-Stil leuchtet jeder angezeigte bannbare Buff."
L["Which layer the windows and the collapsed icon draw on, relative to other frames on screen."] = "Auf welcher Schicht die Fenster und das eingeklappte Symbol relativ zu anderen Fenstern auf dem Bildschirm gezeichnet werden."
L["Which of the season's crests this block shows."] = "Welches Wappen der Saison dieser Block anzeigt."
L["Which way spell flyouts (e.g. Wild Mushroom, Tiger's Fury) open from this bar. Automatic opens away from the nearest screen edge."] = "In welche Richtung sich Zauber-Flyouts (z. B. Wilder Pilz, Tigerwut) von dieser Leiste aus öffnen. „Automatisch“ öffnet vom nächsten Bildschirmrand weg."
L["Which way the windows extend from the collapsed icon when they open. The close button always lands at that same corner."] = "In welche Richtung sich die Fenster beim Öffnen vom eingeklappten Symbol aus ausdehnen. Die Schließen-Schaltfläche landet immer in derselben Ecke."
L["While either grouping toggle is on, drop the trailing block of empty slots so the view only shows items. Turn this off to keep the free slots visible for depositing."] = "Solange einer der Gruppierungsschalter aktiv ist, wird der abschließende Block leerer Plätze entfernt, sodass die Ansicht nur Gegenstände zeigt. Deaktiviere dies, um die freien Plätze zum Einlagern sichtbar zu halten."
L["While on a glide-capable mount, ground included, where Blizzard shows its vigor HUD. Skyriding (Airborne) additionally requires you to be flying."] = "Während du auf einem gleitfähigen Reittier bist, einschließlich am Boden, wo Blizzard sein Elan-HUD anzeigt. „Himmelsreiten (in der Luft)“ erfordert zusätzlich, dass du fliegst."
L["While resting, in a city or at an inn."] = "Während du rastest, in einer Stadt oder einem Gasthaus."
L["While seated in a vehicle."] = "Während du in einem Fahrzeug sitzt."
L["While you are inside a house or plot."] = "Während du dich in einem Haus oder auf einem Grundstück befindest." -- TODO: confirmar termo oficial
