L["Width matched to CDM: Cooldowns. Unmatch in Unlock Mode to edit."] = "Breite an CDM: Abklingzeiten angeglichen. Im Entsperrmodus lösen, um zu bearbeiten."
L["Wind Shear\n(Focus)"] = "Windschur\n(Fokus)"
L["Window & Bar Border Styles"] = "Rahmenstile für Fenster & Leisten"
L["Window header, bar and timer text"] = "Text für Fenster-Kopfzeile, Leiste und Timer"
L["Window scale, icon zoom and item level settings are shared with the Bags page."] = "Einstellungen für Fensterskalierung, Symbolzoom und Gegenstandsstufe werden mit der Taschen-Seite geteilt."
L["Window skins changed for this profile. A UI reload is needed to apply them."] = "Fenster-Skins für dieses Profil geändert. Ein UI-Neuladen ist erforderlich, um sie anzuwenden."
L["With health decimals on, full health renders 100% instead of 100.0% while real decimals like 99.5% stay"] = "Bei aktivierten Gesundheits-Dezimalstellen wird volle Gesundheit als 100% statt 100,0% dargestellt, während echte Dezimalstellen wie 99,5% erhalten bleiben"
L["With the Rectangular shape, player and party arrows no longer draw in the hidden bands above and below the map, and combat transitions no longer leave the map cut off wrong."] = "Bei der rechteckigen Form werden Spieler- und Gruppenpfeile nicht mehr in den ausgeblendeten Bändern über und unter der Karte gezeichnet, und Kampfübergänge schneiden die Karte nicht mehr falsch ab."
L["Works in and out of combat, unlike Auto-Repair. When a group-wide raid buff's column header shows it's missing on someone, the icon blinks and sends the buff's spell link. In a raid, left-click reaches a provider in groups 1-4 and right-click one in groups 5-8; outside a raid, left-click reaches the only provider found. Hovering the icon always shows who each click would whisper, or that everyone already has it."] = "Funktioniert im und außerhalb des Kampfes, anders als Auto-Reparatur. Wenn die Kopfzeilen-Spalte eines gruppenweiten Schlachtzugs-Buffs zeigt, dass er jemandem fehlt, blinkt das Symbol und sendet den Zauberlink des Buffs. In einem Schlachtzug erreicht Linksklick einen Spender in den Gruppen 1-4 und Rechtsklick einen in den Gruppen 5-8; außerhalb eines Schlachtzugs erreicht Linksklick den einzigen gefundenen Spender. Das Überfahren des Symbols zeigt immer, wen jeder Klick anflüstern würde, oder dass bereits jeder den Buff hat."
