L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "Du hast den Standardwert einer Einstellung geändert, die Überschreibungen besitzt. Überschreibungen behalten ihre eigenen Werte, daher erreicht diese Änderung nicht die davon abgedeckten Spezialisierungen oder Bedingungen. Um sie für eine Überschreibung zu ändern, wähle diese Überschreibung über das Klassensymbol neben der Modul-Suchleiste aus und bearbeite sie dort."
